-- =============================================================================
-- 467 — LE CAHIER D'EXERCICES DE 6E (partie 1)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/6e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 467 --niveau 6e --fichiers anglais.n1,anglais.n2,arts-plastiques.n1,emc.n1 --suffixe 1 > supabase/contenu/467_exercices_6e_1.sql
--
-- 81 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   anglais.n1              27 exercices · 9 chapitres
--   anglais.n2              24 exercices · 8 chapitres
--   arts-plastiques.n1       9 exercices · 3 chapitres
--   emc.n1                  21 exercices · 7 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('6189bb4a-dbc2-592e-86e6-046830208547'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dans la chambre de Zoe","competence":"observer-schema","situation":"Zoe, 11 ans, te fait visiter sa chambre à Brighton. Elle montre des objets proches d’elle et d’autres plus loin. Regarde bien où chaque objet se trouve.","documents":[{"id":"chambre","type":"schema","titre":"Zoe’s bedroom","source":"Schéma dessiné pour l’exercice","largeur":320,"hauteur":210,"elements":[{"forme":"ligne","de":[170,20],"a":[170,190],"style":"pointilles","teinte":"gris"},{"forme":"texte","x":85,"y":22,"texte":"near Zoe","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"texte","x":245,"y":22,"texte":"far from Zoe","taille":"petit","italique":true,"ancre":"milieu"},{"forme":"emoji","x":32,"y":112,"emoji":"🧒","taille":44,"id":"z1"},{"forme":"texte","x":32,"y":140,"texte":"Zoe","taille":"petit","ancre":"milieu"},{"forme":"emoji","x":105,"y":80,"emoji":"📖","taille":34,"id":"z2","zone":true},{"forme":"texte","x":105,"y":110,"texte":"a book","taille":"petit","ancre":"milieu"},{"forme":"emoji","x":105,"y":150,"emoji":"✏️✏️","taille":32,"id":"z3","zone":true},{"forme":"texte","x":105,"y":180,"texte":"two pencils","taille":"petit","ancre":"milieu"},{"forme":"emoji","x":250,"y":70,"emoji":"⏰","taille":34,"id":"z4","zone":true},{"forme":"texte","x":250,"y":100,"texte":"a clock","taille":"petit","ancre":"milieu"},{"forme":"emoji","x":250,"y":150,"emoji":"🐦🐦","taille":32,"id":"z5","zone":true},{"forme":"texte","x":250,"y":180,"texte":"two birds","taille":"petit","ancre":"milieu"}]}],"questions":[{"enonce":"Zoe montre ses oiseaux de loin et dit : “**Those** are my pets!” Touche l’objet dont elle parle.","aide":"Those = éloigné + pluriel. Cherche, de l’autre côté du trait, des objets au pluriel.","type":"zone","document":"chambre","multiple":false},{"enonce":"Complète ce que dit Zoe.","aide":"Le livre est près de Zoe, l’horloge est loin. Les deux objets sont au singulier.","type":"trous","segments":[0," is my book. ",1," is my clock."],"banque":["these","those","that","this"]},{"enonce":"Associe chaque objet au bon démonstratif.","aide":"Pose-toi deux questions : proche ou éloigné ? singulier ou pluriel ?","type":"association","gauche":[{"id":"g0","texte":"the book"},{"id":"g1","texte":"the pencils"},{"id":"g2","texte":"the clock"},{"id":"g3","texte":"the birds"}],"droite":[{"id":"d0","texte":"that"},{"id":"d1","texte":"these"},{"id":"d2","texte":"those"},{"id":"d3","texte":"this"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"**Les deux oiseaux** : *those* s’emploie pour des objets **éloignés** et au **pluriel**. Les crayons sont au pluriel mais près de Zoe : on dirait *these*."},{"cle":{"type":"trous","trous":[["this"],["that"]]},"affichage":"this · that","explication":"**This** is my book (proche, singulier) et **that** is my clock (éloigné, singulier). *These* et *those* sont pour le pluriel."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"**this** book (proche, 1) · **these** pencils (proches, 2) · **that** clock (éloignée, 1) · **those** birds (éloignés, 2)."}]$ex$::jsonb),
  ('6189bb4a-dbc2-592e-86e6-046830208547'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une fête chez Ben","competence":"comprendre-langue","situation":"Ben invite Emma à sa fête d’anniversaire. Il lui présente son frère et ses amis, et ils parlent de ce qu’ils voient autour d’eux.","documents":[{"id":"fete","type":"dialogue","modele":"sms","titre":"At the party","source":"Dialogue écrit pour l’exercice","participants":[{"nom":"Ben","emoji":"👦","cote":"gauche"},{"nom":"Emma","emoji":"👧","cote":"droite"},{"nom":"Sam","emoji":"🧑","cote":"gauche"}],"repliques":[{"qui":"Ben","texte":"Emma, this is my brother, Sam."},{"qui":"Emma","texte":"Hi, Sam! Is that your football over there?"},{"qui":"Sam","texte":"Yes, it is. And those boys are in my team."},{"qui":"Emma","texte":"Nice! What are these on the table?"},{"qui":"Ben","texte":"These are our new trainers."}]}],"questions":[{"enonce":"Touche les **deux** démonstratifs qui parlent de quelque chose d’**éloigné**.","aide":"Emma et Sam parlent de choses “over there”, là-bas. Quels mots les montrent de loin ?","type":"zone","document":"fete","multiple":true},{"enonce":"Emma demande : “What are **these** on the table?” Pourquoi dit-elle *these* ?","aide":"These = le pluriel de this. Et this sert pour ce qui est près.","type":"choix","options":[{"id":"a","texte":"Les objets sont proches et au pluriel."},{"id":"b","texte":"Les objets sont proches et au singulier."},{"id":"c","texte":"Les objets sont éloignés et au singulier."},{"id":"d","texte":"Les objets sont éloignés et au pluriel."}],"multiple":false},{"enonce":"Emma montre des chaussures de foot sur une étagère, loin d’elle. Remets sa phrase dans l’ordre.","aide":"Les chaussures sont loin et il y en a plusieurs : quel démonstratif ouvre la phrase ?","type":"ordre","items":[{"id":"a","texte":"are"},{"id":"b","texte":"new"},{"id":"c","texte":"boots"},{"id":"d","texte":"Those"}]},{"enonce":"Associe chaque situation à la bonne phrase.","aide":"Au téléphone et pour présenter quelqu’un, l’anglais emploie this. Pour ce qui est loin, that.","type":"association","gauche":[{"id":"g0","texte":"Présenter ton frère"},{"id":"g1","texte":"Te présenter au téléphone"},{"id":"g2","texte":"Demander ce qu’il y a là-bas"},{"id":"g3","texte":"Parler de choses près de toi"}],"droite":[{"id":"d0","texte":"This is my brother."},{"id":"d1","texte":"Hello, this is Ben."},{"id":"d2","texte":"These are my trainers."},{"id":"d3","texte":"What’s that?"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m18"]},"explication":"**that** (le ballon, loin, singulier) et **those** (les garçons, loin, pluriel). *This* et *these* parlent de ce qui est près."},{"cle":{"type":"choix","ids":["a"]},"explication":"*These* = **proche + pluriel**. La réponse de Ben (“These are our new trainers”) montre bien plusieurs chaussures, tout près d’eux."},{"cle":{"type":"ordre","ids":["d","c","a","b"]},"explication":"**Those boots are new.** : démonstratif, nom, verbe *be*, adjectif. On choisit *those* : éloigné + pluriel."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"On dit **this** pour présenter quelqu’un ou se présenter au téléphone, **that** pour ce qui est loin, **these** pour plusieurs choses proches."}]$ex$::jsonb),
  ('6189bb4a-dbc2-592e-86e6-046830208547'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une carte postale de Londres","competence":"comprendre-langue","situation":"Jack passe une semaine à Londres avec sa classe. Il écrit une carte postale à son amie Lucie, puis il rédige le début d’une deuxième carte. Les petits mots comptent : près ou loin, un seul ou plusieurs ?","documents":[{"id":"carte1","type":"fiche","modele":"carte-postale","titre":"Postcard 1","source":"Carte écrite pour l’exercice","entete":"Hello from London!","sousTitre":"To: Lucie","emoji":"💂","teinte":"corail","lignes":[{"texte":"This morning we are at the Tower of London.","id":"z1"},{"texte":"These birds near me are ravens.","id":"z2"},{"texte":"That bridge over there is Tower Bridge.","id":"z3"},{"texte":"Those buses over there are red.","id":"z4"},{"texte":"These days it is cold here.","id":"z5"},{"texte":"This is my new friend, Ollie.","id":"z6"}],"pied":"See you soon! — Jack"}],"questions":[{"enonce":"Deux lignes parlent d’un **moment** (et non d’un objet ou d’une personne). Touche-les.","aide":"Cherche des expressions qui disent quand : le matin, ces jours-ci.","type":"zone","document":"carte1","multiple":true},{"enonce":"Range ces phrases de la carte selon ce que le démonstratif montre.","aide":"Cherche les petits mots “near me” ou “over there”, puis vérifie que le démonstratif est d’accord.","type":"categories","categories":[{"id":"c0","texte":"Près de Jack"},{"id":"c1","texte":"Loin de Jack"}],"items":[{"id":"i0","texte":"That bridge over there is Tower Bridge."},{"id":"i1","texte":"Those buses over there are red."},{"id":"i2","texte":"This is my new friend, Ollie."},{"id":"i3","texte":"These birds near me are ravens."}]},{"enonce":"Jack écrit une deuxième carte. Complète-la avec le bon démonstratif.","aide":"Pour chaque trou : regarde le nom (singulier ou pluriel) et le petit mot “here” ou “over there”.","type":"trous","segments":[0," days the weather is cold. ",1," picture here is beautiful. ",2," statue over there is old. ",3," dinosaurs over there are big."],"banque":["this","those","these","that"]},{"enonce":"Quelle phrase est correcte ?","aide":"Le nom “books” est au pluriel : le démonstratif doit l’être aussi.","type":"choix","options":[{"id":"a","texte":"This books are old."},{"id":"b","texte":"Those book are old."},{"id":"c","texte":"That books are old."},{"id":"d","texte":"Those books are old."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z5"]},"explication":"**This morning** (ce matin) et **these days** (ces jours-ci) sont des expressions de temps. Dans les autres lignes, les démonstratifs montrent des oiseaux, un pont, des bus, un ami."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"**Près** : these (birds) et this (Ollie). **Loin** : that (bridge) et those (buses). Le choix dépend de la distance ET du nombre."},{"cle":{"type":"trous","trous":[["these"],["this"],["that"],["those"]]},"affichage":"these · this · that · those","explication":"**These** days (expression du présent, pluriel) · **This** picture here (proche, singulier) · **That** statue over there (loin, singulier) · **Those** dinosaurs over there (loin, pluriel)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Those books are old.** : *books* est pluriel, donc *these* ou *those*. *That* et *this* sont des singuliers, et *Those book* ne s’accorde pas."}]$ex$::jsonb),
  ('8fefaa83-c23d-51ce-ae85-da9c9c22a34b'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La boîte des objets trouvés","competence":"lire-tableau","situation":"À la fin de la journée, Mme Cole range la boîte des objets trouvés de l’école. Chaque objet a un propriétaire.","documents":[{"id":"objets","type":"tableau","titre":"Lost property","source":"Tableau écrit pour l’exercice","colonnes":["Object","Owner"],"lignes":[["the football","Tom"],["the red bag","Maya"],["the keys","Mr Dean"],["the notebook","Ana"]]}],"questions":[{"enonce":"Touche le nom du propriétaire du sac rouge.","aide":"Trouve d’abord la ligne “the red bag”, puis lis la colonne Owner.","type":"zone","document":"objets","multiple":false},{"enonce":"Complète les phrases de Mme Cole.","aide":"Pour dire “le sac de Maya”, on met le possesseur d’abord, puis ’s, puis l’objet.","type":"trous","segments":["This is ",0," red bag. These are ",1," keys."],"banque":["Mr Dean","Mr Dean’s","Mr Deans","Maya","Mayas","Maya’s"]},{"enonce":"Mme Cole montre le cahier. Remets sa phrase dans l’ordre.","aide":"Le possesseur avec ’s se place juste devant l’objet.","type":"ordre","items":[{"id":"a","texte":"Ana’s"},{"id":"b","texte":"is"},{"id":"c","texte":"It"},{"id":"d","texte":"notebook"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le sac rouge est à **Maya**."},{"cle":{"type":"trous","trous":[["maya s"],["mr dean s"]]},"affichage":"Maya’s · Mr Dean’s","explication":"**Maya’s** red bag et **Mr Dean’s** keys : possesseur + ’s + objet. On n’emploie pas *of* pour une personne."},{"cle":{"type":"ordre","ids":["c","b","a","d"]},"explication":"**It is Ana’s notebook.** : le possesseur (*Ana’s*) vient avant l’objet, à l’inverse du français « le cahier d’Ana »."}]$ex$::jsonb),
  ('8fefaa83-c23d-51ce-ae85-da9c9c22a34b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’album photo de la famille","competence":"manier-langue","situation":"Léa prépare son album photo et écrit une légende sous chaque photo. À toi de choisir le bon adjectif possessif : il s’accorde avec la personne qui possède, pas avec l’objet.","documents":[{"id":"album","type":"tableau","titre":"Photo album","source":"Tableau écrit pour l’exercice","colonnes":["Owner","Who is it?","Thing"],"lignes":[["Ben","a boy","a bike"],["Lisa","a girl","a guitar"],["the house","a building","a garden"],["Ben and Lisa","two children","a tent"]]}],"questions":[{"enonce":"Dans quelle case lis-tu le possesseur qui demande **its** ?","aide":"Its se dit quand le possesseur n’est ni une personne ni un groupe de personnes.","type":"zone","document":"album","multiple":false},{"enonce":"Complète les légendes avec le bon adjectif possessif.","aide":"Regarde qui possède chaque objet : un garçon, une fille, une maison, deux enfants.","type":"trous","segments":["This is ",0," bike. This is ",1," guitar. This is ",2," garden. This is ",3," tent."],"banque":["my","his","her","our","their","its"]},{"enonce":"Associe chaque adjectif possessif à son pronom possessif.","aide":"Le pronom remplace tout le groupe : “my book” devient “mine”.","type":"association","gauche":[{"id":"g0","texte":"my"},{"id":"g1","texte":"your"},{"id":"g2","texte":"her"},{"id":"g3","texte":"our"},{"id":"g4","texte":"their"}],"droite":[{"id":"d0","texte":"yours"},{"id":"d1","texte":"hers"},{"id":"d2","texte":"theirs"},{"id":"d3","texte":"ours"},{"id":"d4","texte":"mine"}]},{"enonce":"Quelle phrase est correcte ?","aide":"It’s veut toujours dire “it is”. Et l’adjectif se place devant le nom.","type":"choix","options":[{"id":"a","texte":"The dog likes its ball."},{"id":"b","texte":"The dog likes the ball its."},{"id":"c","texte":"The dog likes it’s ball."},{"id":"d","texte":"The dog likes ball its."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"**The house** : une maison n’est ni un garçon ni une fille, on dit donc *its garden*."},{"cle":{"type":"trous","trous":[["his"],["her"],["its"],["their"]]},"affichage":"his · her · its · their","explication":"**his** bike (Ben, un garçon) · **her** guitar (Lisa, une fille) · **its** garden (la maison) · **their** tent (Ben et Lisa)."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g4":"d2","g3":"d3","g0":"d4"}},"explication":"my → **mine** · your → **yours** · her → **hers** · our → **ours** · their → **theirs**. Le pronom s’emploie sans nom derrière."},{"cle":{"type":"choix","ids":["a"]},"explication":"**its ball** : *its* (sans apostrophe) est le possessif. *It’s* = *it is*."}]$ex$::jsonb),
  ('8fefaa83-c23d-51ce-ae85-da9c9c22a34b'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le chiot de Mia","competence":"manier-langue","situation":"Mia a un nouveau chiot et en parle à son ami Jake par message. Dans la même journée, la classe prépare une exposition : à toi de dire à qui appartiennent les objets.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Mia et Jake","source":"Messages écrits pour l’exercice","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Jake","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Look at my new puppy! Its name is Coco."},{"qui":"Jake","texte":"Cute! Is it your parents’ dog?"},{"qui":"Mia","texte":"No, it is mine. Coco loves it’s new bed, too."}]},{"id":"expo","type":"tableau","titre":"The exhibition","source":"Tableau écrit pour l’exercice","colonnes":["Thing","Owner"],"lignes":[["a bike","Paul"],["a car","my parents"],["a room","the children"],["some bags","the girls"]]}],"questions":[{"enonce":"Dans le dernier message de Mia, un mot est faux. Touche-le.","aide":"Le mot veut dire “son” (le lit du chiot). Est-ce que “it is new bed” a un sens ?","type":"zone","document":"sms","multiple":false},{"enonce":"Complète les légendes de l’exposition.","aide":"Pluriel en -s : on ajoute seulement l’apostrophe. Pluriel irrégulier (children) : on garde ’s.","type":"trous","segments":["This is ",0," bike. This is ",1," car. This is ",2," room. These are ",3," bags."],"banque":["the girl’s","Paul’s","the girls’","my parents’","my parents’s","Pauls","the children’s","the childrens’"]},{"enonce":"Range ces mots selon leur emploi.","aide":"Un pronom ne peut pas être suivi d’un nom : “mine” se dit seul.","type":"categories","categories":[{"id":"c0","texte":"Adjectif possessif (devant un nom)"},{"id":"c1","texte":"Pronom possessif (seul)"}],"items":[{"id":"i0","texte":"her"},{"id":"i1","texte":"theirs"},{"id":"i2","texte":"their"},{"id":"i3","texte":"mine"},{"id":"i4","texte":"hers"},{"id":"i5","texte":"my"}]},{"enonce":"Mia répond : “No, it is **mine**.” Que remplace *mine* ?","aide":"Mia parle d’elle : quel adjectif possessif correspond à “I” ?","type":"choix","options":[{"id":"a","texte":"their puppy"},{"id":"b","texte":"her puppy"},{"id":"c","texte":"your puppy"},{"id":"d","texte":"my puppy"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"Il faut **its** (le possessif), pas *it’s*, qui signifie *it is*."},{"cle":{"type":"trous","trous":[["paul s"],["my parents"],["the children s"],["the girls"]]},"affichage":"Paul’s · my parents’ · the children’s · the girls’","explication":"**Paul’s** bike · **my parents’** car (pluriel en -s) · **the children’s** room (pluriel irrégulier) · **the girls’** bags (pluriel en -s)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c1","i5":"c0"}},"explication":"On écrit **my / their / her** + nom, mais **mine / theirs / hers** tout seuls : “It is mine.”"},{"cle":{"type":"choix","ids":["d"]},"explication":"**Mine** = *my puppy* (I → my → mine). Le chiot est à Mia."}]$ex$::jsonb),
  ('ad4cd5f4-49f1-5bb3-abc1-ab77aa0431c0'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dans le frigo des Smith","competence":"comprendre-langue","situation":"Ella ouvre le frigo avec sa maman, à Manchester. Elles regardent ce qu’il reste avant de faire les courses.","documents":[{"id":"frigo","type":"dialogue","modele":"sms","titre":"In the kitchen","source":"Dialogue écrit pour l’exercice","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Ella","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"Is there any milk in the fridge?"},{"qui":"Ella","texte":"Yes, there is some milk and there are some eggs."},{"qui":"Mum","texte":"And there aren’t any apples. We need to go shopping!"}]}],"questions":[{"enonce":"Touche les **deux** mots *any* de la conversation.","aide":"Ils sont dans une question et dans une phrase négative.","type":"zone","document":"frigo","multiple":true},{"enonce":"Complète ce que dit Ella.","aide":"Le lait ne se compte pas ; les œufs, si. Et la dernière phrase est une question.","type":"trous","segments":["There ",0," some milk. There ",1," some eggs. Is there ",2," cheese?"],"banque":["any","is","some","are"]},{"enonce":"Ella demande poliment du jus de fruit : “Can I have ___ juice, please?”","aide":"Quand on demande ou qu’on propose quelque chose, il y a une exception à la règle de la question.","type":"choix","options":[{"id":"a","texte":"much"},{"id":"b","texte":"many"},{"id":"c","texte":"any"},{"id":"d","texte":"some"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m20"]},"explication":"**any** s’emploie dans les questions (*Is there any milk?*) et les négations (*There aren’t any apples*). Dans une phrase affirmative, on dit *some*."},{"cle":{"type":"trous","trous":[["is"],["are"],["any"]]},"affichage":"is · are · any","explication":"There **is** (singulier ou indénombrable) some milk · there **are** (pluriel) some eggs · is there **any** cheese ? (question)."},{"cle":{"type":"choix","ids":["d"]},"explication":"**some** : dans une question où l’on demande ou propose quelque chose, on garde *some*."}]$ex$::jsonb),
  ('ad4cd5f4-49f1-5bb3-abc1-ab77aa0431c0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La fête de Jess","competence":"lire-tableau","situation":"Jess organise une fête dans son jardin. Elle a noté ce qu’elle a déjà acheté.","documents":[{"id":"courses","type":"tableau","titre":"Jess’s party list","source":"Liste écrite pour l’exercice","colonnes":["Thing","Quantity"],"lignes":[["apples","12"],["pizzas","8"],["lemonade","10 litres"],["juice","1 litre"],["chairs","2"]]}],"questions":[{"enonce":"Range les articles de la liste.","aide":"Peut-on compter les choses une par une ? On dit “three apples” mais pas “three lemonades”.","type":"categories","categories":[{"id":"c0","texte":"How many…?"},{"id":"c1","texte":"How much…?"}],"items":[{"id":"i0","texte":"pizzas"},{"id":"i1","texte":"chairs"},{"id":"i2","texte":"apples"},{"id":"i3","texte":"lemonade"},{"id":"i4","texte":"juice"}]},{"enonce":"Complète les phrases de Jess.","aide":"Regarde les quantités : beaucoup, très peu (on compte), très peu (on ne compte pas).","type":"trous","segments":["There are ",0," apples. There are only ",1," chairs. There is only ",2," juice."],"banque":["a few","a little","any","a lot of","much"]},{"enonce":"Jess demande à sa mère : “How ___ lemonade is there ?”","aide":"La limonade se compte-t-elle en unités ?","type":"choix","options":[{"id":"a","texte":"a few"},{"id":"b","texte":"few"},{"id":"c","texte":"much"},{"id":"d","texte":"many"}],"multiple":false},{"enonce":"Jess veut savoir combien de jus il reste. Remets sa question dans l’ordre.","aide":"La question commence par how much, puis le nom, puis is there.","type":"ordre","items":[{"id":"a","texte":"is"},{"id":"b","texte":"much"},{"id":"c","texte":"How"},{"id":"d","texte":"juice"},{"id":"e","texte":"there"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c0","i3":"c1","i4":"c1"}},"explication":"**How many** pour ce qu’on compte (apples, pizzas, chairs) · **how much** pour ce qu’on ne compte pas (lemonade, juice)."},{"cle":{"type":"trous","trous":[["a lot of"],["a few"],["a little"]]},"affichage":"a lot of · a few · a little","explication":"**a lot of** apples (12) · only **a few** chairs (2, dénombrable) · only **a little** juice (1 litre, indénombrable)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**much** : *lemonade* est indénombrable, donc *How much lemonade…?*. On réserve *many* aux noms qu’on compte."},{"cle":{"type":"ordre","ids":["c","b","d","a","e"]},"explication":"**How much juice is there ?** : *How much* + nom indénombrable + *is there*."}]$ex$::jsonb),
  ('ad4cd5f4-49f1-5bb3-abc1-ab77aa0431c0'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les crêpes d’Ana","competence":"manier-langue","situation":"Ana veut préparer des crêpes. Elle regarde sa recette puis part acheter ce qui manque chez le commerçant du coin.","documents":[{"id":"recette","type":"fiche","modele":"recette","titre":"Ana’s pancakes","source":"Recette écrite pour l’exercice","entete":"Pancakes","sousTitre":"For four people","emoji":"🥞","teinte":"ambre","lignes":[{"texte":"**You need:**"},{"texte":"two eggs","id":"z1"},{"texte":"some flour","id":"z2"},{"texte":"some milk","id":"z3"},{"texte":"a little sugar","id":"z4"},{"texte":"a few strawberries","id":"z5"}],"pied":"Enjoy!"},{"id":"boutique","type":"dialogue","modele":"sms","titre":"At the shop","source":"Dialogue écrit pour l’exercice","participants":[{"nom":"Shopkeeper","emoji":"🧑‍🍳","cote":"gauche"},{"nom":"Ana","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Shopkeeper","texte":"Good morning! Can I help you?"},{"qui":"Ana","texte":"Yes, please. Do you have any eggs?"},{"qui":"Shopkeeper","texte":"Yes, we have some eggs, but we don’t have many strawberries."},{"qui":"Ana","texte":"No problem. Can I have some milk, please?"},{"qui":"Shopkeeper","texte":"Of course! Would you like some butter too?"}]}],"questions":[{"enonce":"Range les ingrédients de la recette.","aide":"On dit “two eggs” mais pas “two flours”.","type":"categories","categories":[{"id":"c0","texte":"On les compte"},{"id":"c1","texte":"On ne les compte pas"}],"items":[{"id":"i0","texte":"flour"},{"id":"i1","texte":"eggs"},{"id":"i2","texte":"sugar"},{"id":"i3","texte":"strawberries"},{"id":"i4","texte":"milk"}]},{"enonce":"Dans la conversation, **deux** *some* sont dans une **question**. Touche-les.","aide":"Ana demande quelque chose, puis le commerçant propose quelque chose.","type":"zone","document":"boutique","multiple":true},{"enonce":"Ana vérifie sa recette. Complète ses questions.","aide":"Les œufs se comptent ; le lait non.","type":"trous","segments":["How ",0," eggs do we need? How ",1," milk do we need?"],"banque":["much","many","little","few"]},{"enonce":"Le commerçant dit : “We don’t have **many** strawberries.” Que veut-il dire ?","aide":"Dans une négation, many dit “pas beaucoup”.","type":"choix","options":[{"id":"a","texte":"Il n’y a pas de lait."},{"id":"b","texte":"Il y a quelques fraises, c’est largement assez."},{"id":"c","texte":"Il y a peu de fraises, ce n’est pas assez."},{"id":"d","texte":"Il y a beaucoup de fraises."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"**Dénombrables** : eggs, strawberries · **indénombrables** : flour, milk, sugar. C’est ce qui décide entre *many/few* et *much/little*."},{"cle":{"type":"zone","ids":["m29","m37"]},"explication":"On garde **some** dans une question quand on **demande** (*Can I have some milk?*) ou qu’on **propose** (*Would you like some butter?*)."},{"cle":{"type":"trous","trous":[["many"],["much"]]},"affichage":"many · much","explication":"How **many** eggs (dénombrable) · how **much** milk (indénombrable)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Pas beaucoup de fraises** : *don’t have many* annonce un manque. Pour dire « quelques » de façon positive, on dirait *a few*."}]$ex$::jsonb),
  ('c625d09a-d589-5f5b-b4be-f8c4a7b72dd4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La chambre de Zoe, en mots","competence":"comprendre-langue","situation":"Zoe décrit sa chambre dans un petit texte pour son correspondant. Les adjectifs, ces mots qui disent comment sont les choses, sont partout.","documents":[{"id":"chambre","type":"texte","genre":"recit","titre":"My bedroom","source":"Texte écrit pour l’exercice","blocs":["Zoe has a small bedroom. There is a blue bed, a big window and two green chairs. On the wall, there is a yellow clock."]}],"questions":[{"enonce":"Touche **tous** les adjectifs du texte (ils disent comment sont les choses).","aide":"Il y a cinq adjectifs : trois couleurs, et deux mots qui disent la taille.","type":"zone","document":"chambre","multiple":true},{"enonce":"Zoe décrit son sac. Remets la phrase dans l’ordre.","aide":"La taille se dit avant la couleur, et les deux avant le nom.","type":"ordre","items":[{"id":"a","texte":"big"},{"id":"b","texte":"a"},{"id":"c","texte":"She"},{"id":"d","texte":"has"},{"id":"e","texte":"blue"},{"id":"f","texte":"bag"}]},{"enonce":"Associe chaque expression française à sa traduction.","aide":"L’adjectif anglais va devant le nom et ne prend jamais de -s.","type":"association","gauche":[{"id":"g0","texte":"une chaise verte"},{"id":"g1","texte":"deux chaises vertes"},{"id":"g2","texte":"un grand lit"},{"id":"g3","texte":"une petite fenêtre"}],"droite":[{"id":"d0","texte":"a green chair"},{"id":"d1","texte":"a small window"},{"id":"d2","texte":"a big bed"},{"id":"d3","texte":"two green chairs"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m8","m11","m15","m23"]},"explication":"**small, blue, big, green, yellow** : ce sont les adjectifs. Ils se placent devant le nom et ne changent jamais (*two green chairs*)."},{"cle":{"type":"ordre","ids":["c","d","b","a","e","f"]},"explication":"**She has a big blue bag.** : ordre taille → couleur, puis le nom."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g1":"d3"}},"explication":"L’adjectif est **devant** le nom et **invariable** : *a green chair* / *two green chairs* (jamais *greens*)."}]$ex$::jsonb),
  ('c625d09a-d589-5f5b-b4be-f8c4a7b72dd4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La sortie de classe","competence":"manier-langue","situation":"Leo et Mia discutent par messages le jour d’une sortie scolaire. L’un s’ennuie, l’autre est ravie, et le bus est un peu chaud.","documents":[{"id":"sortie","type":"dialogue","modele":"sms","titre":"School trip","source":"Messages écrits pour l’exercice","participants":[{"nom":"Leo","emoji":"👦","cote":"gauche"},{"nom":"Mia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Leo","texte":"I am very bored. This lesson is boring."},{"qui":"Mia","texte":"Really? I am excited. The school trip is exciting!"},{"qui":"Leo","texte":"Yes, but the bus is too hot and I am tired."}]}],"questions":[{"enonce":"Touche les **trois** adjectifs qui disent ce que **ressent** une personne (terminaison **-ed**).","aide":"Cherche des mots en -ed après “I am”.","type":"zone","document":"sortie","multiple":true},{"enonce":"Leo parle du film de la sortie. Complète.","aide":"Le film provoque l’ennui ; Leo ressent l’ennui.","type":"trous","segments":["The film is ",0,". I am ",1,"."],"banque":["tired","exciting","bored","boring"]},{"enonce":"Leo dit : “The bus is **too** hot.” Quelle phrase a le même sens ?","aide":"Too exprime un excès : plus que ce qu’on veut.","type":"choix","options":[{"id":"a","texte":"The bus is not hot."},{"id":"b","texte":"The bus is hot and that is a problem."},{"id":"c","texte":"The bus is a little hot, and it is perfect."},{"id":"d","texte":"The bus is hot and that is nice."}],"multiple":false},{"enonce":"Mia décrit son chat. Remets sa phrase dans l’ordre.","aide":"Ordre des adjectifs : taille, âge, couleur.","type":"ordre","items":[{"id":"a","texte":"old"},{"id":"b","texte":"black"},{"id":"c","texte":"cat"},{"id":"d","texte":"a"},{"id":"e","texte":"small"},{"id":"f","texte":"has"},{"id":"g","texte":"She"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m3","m11","m27"]},"explication":"**bored, excited, tired** décrivent ce que Leo et Mia ressentent. Les mots en *-ing* (*boring*, *exciting*) décrivent ce qui provoque le sentiment."},{"cle":{"type":"trous","trous":[["boring"],["bored"]]},"affichage":"boring · bored","explication":"The film is **boring** (il provoque l’ennui) · I am **bored** (je m’ennuie). Dire *I am boring*, ce serait « je suis ennuyeux »."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Too** = trop : c’est un problème. *Very hot* serait un simple constat."},{"cle":{"type":"ordre","ids":["g","f","d","e","a","b","c"]},"explication":"**She has a small old black cat.** : taille → âge → couleur."}]$ex$::jsonb),
  ('c625d09a-d589-5f5b-b4be-f8c4a7b72dd4'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un sac perdu et des correspondants","competence":"manier-langue","situation":"À Londres, Luca a perdu son sac. Il écrit une affiche pour le retrouver. Plus tard, il présente ses correspondants à la classe.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","titre":"Lost bag","source":"Affiche écrite pour l’exercice","entete":"LOST!","sousTitre":"A nice big old brown bag","emoji":"🎒","teinte":"brun","lignes":[{"texte":"nice","id":"z1"},{"texte":"big","id":"z2"},{"texte":"old","id":"z3"},{"texte":"brown","id":"z4"}],"pied":"Please call Luca at school."},{"id":"amis","type":"tableau","titre":"Pen friends","source":"Tableau écrit pour l’exercice","colonnes":["Name","Country"],"lignes":[["Marta","Spain"],["Luca","Italy"],["Pierre","France"],["Emma","England"]]}],"questions":[{"enonce":"Range ces adjectifs selon ce qu’ils décrivent.","aide":"L’ordre de l’affiche est : opinion, taille, âge, couleur.","type":"categories","categories":[{"id":"c0","texte":"Opinion"},{"id":"c1","texte":"Taille"},{"id":"c2","texte":"Âge"},{"id":"c3","texte":"Couleur"}],"items":[{"id":"i0","texte":"big"},{"id":"i1","texte":"brown"},{"id":"i2","texte":"small"},{"id":"i3","texte":"old"},{"id":"i4","texte":"nice"},{"id":"i5","texte":"lovely"}]},{"enonce":"Luca présente ses correspondants. Complète avec la nationalité.","aide":"La nationalité se déduit du pays, et se dit sans article : “She is …”.","type":"trous","segments":["Marta is from Spain. She is ",0,". Luca is from Italy. He is ",1,"."]},{"enonce":"Luca décrit sa voiture. Remets la phrase dans l’ordre.","aide":"Opinion, âge, origine, puis le nom.","type":"ordre","items":[{"id":"a","texte":"a"},{"id":"b","texte":"car"},{"id":"c","texte":"Luca"},{"id":"d","texte":"nice"},{"id":"e","texte":"Italian"},{"id":"f","texte":"has"},{"id":"g","texte":"old"}]},{"enonce":"Quelle phrase est correcte ?","aide":"Après be, une nationalité se dit sans article et sans -s.","type":"choix","options":[{"id":"a","texte":"Pierre is a French."},{"id":"b","texte":"Pierre is Frenchs."},{"id":"c","texte":"Pierre is the French."},{"id":"d","texte":"Pierre is French."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c3","i2":"c1","i3":"c2","i4":"c0","i5":"c0"}},"explication":"**nice, lovely** = opinion · **big, small** = taille · **old** = âge · **brown** = couleur. L’ordre est : opinion → taille → âge → couleur."},{"cle":{"type":"trous","trous":[["spanish"],["italian"]]},"affichage":"Spanish · Italian","explication":"Marta est **Spanish**, Luca est **Italian**. Les nationalités prennent une majuscule et s’emploient sans article."},{"cle":{"type":"ordre","ids":["c","f","a","d","g","e","b"]},"explication":"**Luca has a nice old Italian car.** : opinion → âge → origine."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Pierre is French.** : l’adjectif de nationalité prend une majuscule, reste invariable (pas de -s) et se dit sans article."}]$ex$::jsonb),
  ('dee815b8-34fa-5c98-a28e-31f31cfaa69f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La fiche de Sam","competence":"comprendre-langue","situation":"Sam, un correspondant anglais, se présente sur une petite fiche. À toi de la lire et de parler de lui.","documents":[{"id":"fiche","type":"fiche","modele":"etiquette","titre":"Pen friend card","source":"Fiche écrite pour l’exercice","entete":"My card","sousTitre":"Pen friend","emoji":"🧒","teinte":"bleu","lignes":[{"texte":"Name: Sam","id":"z1"},{"texte":"Age: 12","id":"z2"},{"texte":"Country: England","id":"z3"},{"texte":"Cat: Mo","id":"z4"}]}],"questions":[{"enonce":"En français, on dit « Sam **a** 12 ans ». Touche la ligne qui donne cette information.","aide":"Cherche le mot Age.","type":"zone","document":"fiche","multiple":false},{"enonce":"Complète la présentation de Sam.","aide":"Avec I on emploie am ; avec un nom au singulier (my cat), on emploie is.","type":"trous","segments":["I ",0," Sam. I ",1," 12. My cat ",2," Mo."],"banque":["is","am","have","are"]},{"enonce":"Pose une question à Sam. Remets les mots dans l’ordre.","aide":"Avec be, on inverse le verbe et le sujet : le verbe passe en premier.","type":"ordre","items":[{"id":"a","texte":"from"},{"id":"b","texte":"England"},{"id":"c","texte":"Sam"},{"id":"d","texte":"Is"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La ligne **Age: 12** : en anglais, on dit *Sam is 12* (avec *be*, pas avec *have*)."},{"cle":{"type":"trous","trous":[["am"],["am"],["is"]]},"affichage":"am · am · is","explication":"I **am** Sam · I **am** 12 (pas *I have 12*) · My cat **is** Mo."},{"cle":{"type":"ordre","ids":["d","c","a","b"]},"explication":"**Is Sam from England ?** : *be* passe devant le sujet, sans *do*."}]$ex$::jsonb),
  ('dee815b8-34fa-5c98-a28e-31f31cfaa69f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Il fait froid, j’ai faim","competence":"manier-langue","situation":"Leo rentre du foot avec sa maman. Il a faim, soif… et chaque fois, l’anglais utilise be là où le français dit « avoir ».","documents":[{"id":"dialogue","type":"dialogue","modele":"sms","titre":"After football","source":"Dialogue écrit pour l’exercice","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Leo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"Are you hungry, Leo?"},{"qui":"Leo","texte":"Yes, I am. And I’m also thirsty!"},{"qui":"Mum","texte":"Your sister isn’t hungry. She’s cold."},{"qui":"Leo","texte":"Mum, you’re right. It’s cold today."}]}],"questions":[{"enonce":"Touche la forme **négative** du verbe *be* dans la conversation.","aide":"Cherche un mot qui finit par n’t.","type":"zone","document":"dialogue","multiple":false},{"enonce":"Associe chaque phrase française à son équivalent anglais.","aide":"Là où le français dit « avoir », l’anglais dit être.","type":"association","gauche":[{"id":"g0","texte":"J’ai faim"},{"id":"g1","texte":"J’ai soif"},{"id":"g2","texte":"J’ai froid"},{"id":"g3","texte":"Tu as raison"},{"id":"g4","texte":"J’ai 12 ans"}],"droite":[{"id":"d0","texte":"I am 12"},{"id":"d1","texte":"I am cold"},{"id":"d2","texte":"You are right"},{"id":"d3","texte":"I am thirsty"},{"id":"d4","texte":"I am hungry"}]},{"enonce":"Mum parle de la sœur de Leo. Remets la phrase dans l’ordre.","aide":"La négation se place juste après be.","type":"ordre","items":[{"id":"a","texte":"sister"},{"id":"b","texte":"My"},{"id":"c","texte":"hungry"},{"id":"d","texte":"isn’t"}]},{"enonce":"Complète avec la bonne forme de *be*.","aide":"Hier = passé ; maintenant = présent. Le sujet est we dans les deux cas.","type":"trous","segments":["Yesterday we ",0," at school but now we ",1," at home."],"banque":["was","am","are","were"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13"]},"explication":"**isn’t** = *is not*. Avec *be*, la négation se fait avec *not* juste après le verbe."},{"cle":{"type":"association","paires":{"g4":"d0","g2":"d1","g3":"d2","g1":"d3","g0":"d4"}},"explication":"On emploie **be** : *I am hungry / thirsty / cold*, *you are right*, *I am 12*. C’est le piège du chapitre."},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"**My sister isn’t hungry.** : sujet + *isn’t* + adjectif."},{"cle":{"type":"trous","trous":[["were"],["are"]]},"affichage":"were · are","explication":"Yesterday we **were** at school (prétérit de *be*, pour we) · now we **are** at home (présent)."}]$ex$::jsonb),
  ('dee815b8-34fa-5c98-a28e-31f31cfaa69f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Samedi à la plage","competence":"lire-tableau","situation":"Trois élèves racontent leur samedi. Un tableau dit où ils étaient, et une carte postale montre la plage.","documents":[{"id":"samedi","type":"tableau","titre":"On Saturday","source":"Tableau écrit pour l’exercice","colonnes":["Name","Morning","Afternoon"],"lignes":[["Tom","park","cinema"],["Lily","library","swimming pool"],["Ben and Zoe","beach","beach"]]},{"id":"plage","type":"fiche","modele":"carte-postale","titre":"Beach photo","source":"Carte écrite pour l’exercice","entete":"The beach","sousTitre":"Saturday","emoji":"🏖️","teinte":"bleu","lignes":[{"texte":"There are two dogs on the sand.","id":"z1"},{"texte":"There is a red boat near the sea.","id":"z2"},{"texte":"There are three children in the water.","id":"z3"}],"pied":"Great day!"}],"questions":[{"enonce":"Où Lily **était**-elle samedi après-midi ? Touche la case.","aide":"Trouve la ligne Lily, puis la colonne Afternoon.","type":"zone","document":"samedi","multiple":false},{"enonce":"Complète avec le prétérit de *be*.","aide":"I, he, she, it → was ; you, we, they → were. Le dernier trou est négatif : Tom n’y était pas.","type":"trous","segments":["Tom ",0," at the park in the morning. Ben and Zoe ",1," at the beach. Tom ",2," at the swimming pool."]},{"enonce":"Remets cette question dans l’ordre.","aide":"Where au début, puis be passe avant le sujet.","type":"ordre","items":[{"id":"a","texte":"Ben"},{"id":"b","texte":"Where"},{"id":"c","texte":"were"},{"id":"d","texte":"and"},{"id":"e","texte":"Zoe"}]},{"enonce":"Touche la ligne qui emploie **there is** (un seul objet).","aide":"There is + singulier. Cherche un seul objet.","type":"zone","document":"plage","multiple":false},{"enonce":"Dans quel cas l’anglais emploie-t-il *be* là où le français dit « avoir » ?","aide":"Traduis chaque phrase en français : « j’ai … » ou « je suis … » ?","type":"categories","categories":[{"id":"c0","texte":"be = être"},{"id":"c1","texte":"be = avoir (en français)"}],"items":[{"id":"i0","texte":"I am tired"},{"id":"i1","texte":"They are teachers"},{"id":"i2","texte":"You are right"},{"id":"i3","texte":"She is thirsty"},{"id":"i4","texte":"I am 12"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Lily **was** at the swimming pool in the afternoon."},{"cle":{"type":"trous","trous":[["was"],["were"],["wasn t","was not"]]},"affichage":"was · were · wasn’t","explication":"Tom **was** at the park · Ben and Zoe **were** at the beach · Tom **wasn’t** at the swimming pool (il était au parc puis au cinéma)."},{"cle":{"type":"ordre","ids":["b","c","a","d","e"]},"explication":"**Where were Ben and Zoe ?** : mot interrogatif, *were*, puis le sujet."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**There is a red boat…** : *there is* pour un seul objet, *there are* pour plusieurs (two dogs, three children)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1"}},"explication":"**Être** : I am tired, they are teachers. **Avoir** en français : I am 12, she is thirsty, you are right."}]$ex$::jsonb),
  ('304b7ac9-f45f-5390-be6a-50a0ffbafe37'::uuid, 1, 1, 5, 20, 3,
