   $ex$[{"cle":{"type":"zone","ids":["m12"]},"explication":"**He’s got** blue eyes = *he has got*. Dans « He’s tall », *’s* est *is*."},{"cle":{"type":"trous","trous":[["has"],["has"],["hasn t","has not"]]},"affichage":"has · has · hasn’t","explication":"**Has** Jo’s brother got a bike ? Yes, he **has**. But Jo **hasn’t** got a bike."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2","g3":"d3"}},"explication":"Les quatre emplois : maladie (*headache*), famille (*two brothers*), description (*blue eyes*), possession (*a cat*)."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**is** : He’s tired, She’s happy · **has** : He’s got a car, She’s got two brothers."}]$ex$::jsonb),
