se verbale (ici le verbe do).","type":"ordre","items":[{"id":"a","texte":"do"},{"id":"b","texte":"Did"},{"id":"c","texte":"your"},{"id":"d","texte":"homework"},{"id":"e","texte":"you"}]}]}$ex$::jsonb,
