   $ex${"titre":"Le règlement de la classe","competence":"analyser-document","situation":"Au début de l’année, la classe de 6e lit son règlement affiché au mur.","documents":[{"id":"regles","type":"fiche","modele":"panneau","titre":"Class rules","source":"Règlement écrit pour l’exercice","entete":"Class rules","sousTitre":"Room 12","emoji":"🏫","teinte":"violet","lignes":[{"texte":"You must listen to the teacher.","id":"z1"},{"texte":"You mustn’t run in the corridor.","id":"z2"},{"texte":"You mustn’t eat in the classroom.","id":"z3"},{"texte":"You must raise your hand to speak.","id":"z4"}]}],"questions":[{"enonce":"Touche les **deux** règles qui disent que quelque chose est **interdit**.","aide":"Cherche mustn’t.","type":"zone","document":"regles","multiple":true},{"enonce":"Complète deux règles.","aide":"La première est une obligation. La seconde est une interdiction.","type":"trous","segments":["You ",0," raise your hand to speak. You ",1," run in the corridor."]},{"enonce":"Associe chaque règle à son sens.","aide":"Must = devoir. Mustn’t = interdit.","type":"association","gauche":[{"id":"g0","texte":"You must listen."},{"id":"g1","texte":"You mustn’t run."},{"id":"g2","texte":"You must raise your hand."}],"droite":[{"id":"d0","texte":"Tu dois lever la main."},{"id":"d1","texte":"Tu dois écouter."},{"id":"d2","texte":"Il est interdit de courir."}]}]}$ex$::jsonb,
