  ('a535df67-d7d9-52cb-b4d0-8a1cdb8856af'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La sortie au zoo","competence":"analyser-document","situation":"La classe part au zoo. Le professeur distribue une feuille avec les consignes. Attention : *mustn’t* et *don’t have to* ne veulent pas dire la même chose !","documents":[{"id":"zoo","type":"fiche","modele":"invitation","titre":"School trip to the zoo","source":"Feuille écrite pour l’exercice","entete":"School trip","sousTitre":"The zoo","emoji":"🦒","teinte":"vert","lignes":[{"texte":"You must bring a packed lunch.","id":"z1"},{"texte":"You mustn’t feed the animals.","id":"z2"},{"texte":"You don’t have to bring money: tickets are free.","id":"z3"},{"texte":"You have to wear your school uniform.","id":"z4"}]}],"questions":[{"enonce":"Touche la ligne qui dit qu’il n’est **pas nécessaire** de faire quelque chose (ce n’est pas obligatoire).","aide":"Ce n’est pas interdit : tu es simplement libre de le faire ou non.","type":"zone","document":"zoo","multiple":false},{"enonce":"Associe chaque forme à son sens.","aide":"Mustn’t et don’t have to disent le contraire l’un de l’autre.","type":"association","gauche":[{"id":"g0","texte":"You must"},{"id":"g1","texte":"You mustn’t"},{"id":"g2","texte":"You don’t have to"}],"droite":[{"id":"d0","texte":"C’est obligatoire"},{"id":"d1","texte":"Ce n’est pas obligatoire"},{"id":"d2","texte":"C’est interdit"}]},{"enonce":"Le professeur raconte la semaine dernière. Complète.","aide":"Must n’a pas de passé : on le remplace par une autre expression.","type":"trous","segments":["Last week we ",0," ",1," wear our uniform."],"banque":["have","must","had","to"]},{"enonce":"Remets cette phrase dans l’ordre.","aide":"Don’t have to + verbe à la base.","type":"ordre","items":[{"id":"a","texte":"don’t"},{"id":"b","texte":"money"},{"id":"c","texte":"have"},{"id":"d","texte":"to"},{"id":"e","texte":"We"},{"id":"f","texte":"bring"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**You don’t have to bring money** : pas d’obligation (les billets sont gratuits). Ce n’est pas la même chose que *mustn’t*, qui interdit."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**must** = obligation · **mustn’t** = interdiction · **don’t have to** = pas obligatoire (liberté)."},{"cle":{"type":"trous","trous":[["had"],["to"]]},"affichage":"had · to","explication":"Last week we **had to** wear our uniform : *must* n’a pas de passé, on emploie *had to*."},{"cle":{"type":"ordre","ids":["e","a","c","d","f","b"]},"explication":"**We don’t have to bring money.** : on n’est pas obligé d’apporter de l’argent."}]$ex$::jsonb),
  ('a535df67-d7d9-52cb-b4d0-8a1cdb8856af'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Direction la piscine","competence":"analyser-document","situation":"Lia et Marc vont à la piscine municipale. Marc a les cheveux courts, Lia les cheveux longs. Lis le règlement de la piscine, puis leur conversation.","documents":[{"id":"piscine","type":"fiche","modele":"panneau","titre":"Pool rules","source":"Règlement écrit pour l’exercice","entete":"Pool rules","sousTitre":"Swimming pool","emoji":"🏊","teinte":"bleu","lignes":[{"texte":"You must shower first.","id":"z1"},{"texte":"You mustn’t run.","id":"z2"},{"texte":"You mustn’t push people.","id":"z3"},{"texte":"You have to wear a cap if you have long hair.","id":"z4"},{"texte":"You don’t have to bring a towel: the pool has towels.","id":"z5"}]},{"id":"lm","type":"dialogue","modele":"sms","titre":"Lia and Marc","source":"Messages écrits pour l’exercice","participants":[{"nom":"Marc","emoji":"👦","cote":"gauche"},{"nom":"Lia","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Marc","texte":"Do I have to wear a cap? I’ve got short hair."},{"qui":"Lia","texte":"No, you don’t have to. But I have to wear one. I’ve got long hair."}]}],"questions":[{"enonce":"Marc a les cheveux courts. Touche la règle qu’il **n’est pas obligé** de suivre.","aide":"Cherche la règle qui parle des cheveux.","type":"zone","document":"piscine","multiple":false},{"enonce":"Lia dit : “I **have to** wear one.” D’où vient l’obligation ?","aide":"Regarde la règle de la piscine sur les bonnets.","type":"choix","options":[{"id":"a","texte":"De Lia, selon son envie."},{"id":"b","texte":"De Marc, qui le lui demande."},{"id":"c","texte":"D’aucune règle précise."},{"id":"d","texte":"D’une règle de la piscine."}],"multiple":false},{"enonce":"Range les règles de la piscine.","aide":"Mustn’t = interdit, don’t have to = pas nécessaire, must = obligatoire.","type":"categories","categories":[{"id":"c0","texte":"Interdit"},{"id":"c1","texte":"Pas nécessaire"},{"id":"c2","texte":"Obligatoire"}],"items":[{"id":"i0","texte":"You mustn’t push people."},{"id":"i1","texte":"You don’t have to bring a towel."},{"id":"i2","texte":"You must shower first."},{"id":"i3","texte":"You mustn’t run."}]},{"enonce":"Lia pense à demain. Complète.","aide":"Must n’a pas de futur : on emploie une autre forme avec will.","type":"trous","segments":["Tomorrow Lia will ",0," ",1," wear a cap again."],"banque":["have","had","must","to"]},{"enonce":"Marc donne un conseil à Lia. Remets sa phrase dans l’ordre.","aide":"Should + verbe à la base, sans to.","type":"ordre","items":[{"id":"a","texte":"You"},{"id":"b","texte":"water"},{"id":"c","texte":"more"},{"id":"d","texte":"should"},{"id":"e","texte":"drink"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"**You have to wear a cap if you have long hair** : Marc a les cheveux courts, il n’est donc pas obligé de porter un bonnet."},{"cle":{"type":"choix","ids":["d"]},"explication":"*Have to* exprime une obligation venue de **l’extérieur** : ici le règlement de la piscine. *Must* vient plutôt de celui qui parle."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c0"}},"explication":"**Interdit** : mustn’t run, mustn’t push · **pas nécessaire** : don’t have to bring a towel · **obligatoire** : must shower."},{"cle":{"type":"trous","trous":[["have"],["to"]]},"affichage":"have · to","explication":"Tomorrow Lia **will have to** wear a cap : *must* n’a ni passé ni futur, on emploie *have to* avec *will*."},{"cle":{"type":"ordre","ids":["a","d","e","c","b"]},"explication":"**You should drink more water.** : *should* donne un conseil, moins fort que *must*."}]$ex$::jsonb),
  ('fbca82b1-9d7f-5da1-b5f3-ed6eaf7f9367'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le week-end de Sam et d’Inès","competence":"comprendre-langue","situation":"Sam, ton correspondant anglais, écrit à Inès pour raconter son week-end. Elle lui répond. Les deux enfants parlent de ce qu’ils ont fait.","documents":[{"id":"msg","type":"dialogue","modele":"sms","titre":"Messages","source":"Messages écrits pour l’exercice.","participants":[{"nom":"Sam","emoji":"👦","cote":"gauche"},{"nom":"Inès","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Sam","texte":"Hi Inès! Last weekend I visited my grandad. We played football and I watched a film."},{"qui":"Inès","texte":"Cool! I stayed at home. I baked a cake with Mum."},{"qui":"Sam","texte":"Yum! I love cake."}]}],"questions":[{"enonce":"Sam et Inès racontent leur week-end passé. Touche **tous les verbes au prétérit** (les verbes qui se terminent par -ed).","aide":"Cherche les verbes qui racontent ce qui s’est passé le week-end dernier : ils finissent tous par -ed. « love » est au présent.","type":"zone","document":"msg","multiple":true},{"enonce":"Quel groupe de mots, au début du message de Sam, annonce qu’il parle du **passé** ?","aide":"« last » veut dire « dernier » : est-ce passé ou à venir ?","type":"choix","options":[{"id":"a","texte":"Every weekend"},{"id":"b","texte":"Right now"},{"id":"c","texte":"Next weekend"},{"id":"d","texte":"Last weekend"}],"multiple":false},{"enonce":"Complète la phrase avec le bon verbe.","aide":"Le week-end est passé : il faut le prétérit. Attention, « bakeed » n’existe pas !","type":"trous","segments":["Inès ",0," a cake with her mum."],"banque":["bakes","baked","bakeed","bake"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m9","m13","m18","m22"]},"explication":"Les verbes au prétérit sont **visited, played, watched, stayed** et **baked** : on a ajouté **-ed** au verbe de base. « love » (dans « I love cake ») reste au présent."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Last weekend** (le week-end dernier) est un repère de temps du passé : il réclame le prétérit. « Every weekend » dit une habitude, « Next weekend » le futur, « Right now » le présent."},{"cle":{"type":"trous","trous":[["baked"]]},"affichage":"baked","explication":"Inès **baked** a cake : bake finit déjà par un -e, on ajoute seulement **-d** (bake → baked)."}]$ex$::jsonb),
  ('fbca82b1-9d7f-5da1-b5f3-ed6eaf7f9367'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Le journal de Lola, samedi dernier","competence":"manier-langue","situation":"Lola tient un journal en anglais. Samedi dernier, elle a fait plein de choses. Aide-toi de son journal pour étudier les verbes au prétérit.","documents":[{"id":"journal","type":"fiche","modele":"affiche","entete":"Lola’s diary","sousTitre":"Last Saturday","emoji":"📔","teinte":"rose","lignes":[{"texte":"I got up at eight.","id":"z1"},{"texte":"I had cereal for breakfast.","id":"z2"},{"texte":"We played in the park.","id":"z3"},{"texte":"I studied for my test.","id":"z4"},{"texte":"I saw a film in the evening.","id":"z5"}],"pied":"Journal imaginé pour l’exercice"}],"questions":[{"enonce":"Trois phrases du journal contiennent un verbe **irrégulier** (qui ne prend pas -ed). Touche-les.","aide":"Un verbe régulier finit par -ed. Les autres sont irréguliers : ils changent de forme (go → went).","type":"zone","document":"journal","multiple":true},{"enonce":"Range ces verbes au prétérit selon la façon dont leur -ed s’écrit.","aide":"Regarde le verbe de base : se termine-t-il par -e ? par consonne + y ? est-il court (consonne-voyelle-consonne) ?","type":"categories","categories":[{"id":"c0","texte":"On ajoute seulement -d"},{"id":"c1","texte":"y devient -ied"},{"id":"c2","texte":"On double la consonne + -ed"},{"id":"c3","texte":"On ajoute simplement -ed"}],"items":[{"id":"i0","texte":"danced"},{"id":"i1","texte":"stopped"},{"id":"i2","texte":"walked"},{"id":"i3","texte":"studied"},{"id":"i4","texte":"liked"},{"id":"i5","texte":"played"},{"id":"i6","texte":"tried"},{"id":"i7","texte":"planned"}]},{"enonce":"Remets les mots dans l’ordre pour poser une question sur le journal de Lola.","aide":"Après « Did » et le sujet, le verbe reste à la base verbale.","type":"ordre","items":[{"id":"a","texte":"on Saturday?"},{"id":"b","texte":"Did"},{"id":"c","texte":"study"},{"id":"d","texte":"Lola"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2","z5"]},"explication":"**got** (get), **had** (have) et **saw** (see) sont irréguliers : il faut les apprendre. *played* et *studied* sont réguliers (-ed)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c3","i3":"c1","i4":"c0","i5":"c3","i6":"c1","i7":"c2"}},"explication":"like → liked et dance → danced (déjà un -e : **-d**) · study → studied et try → tried (consonne + y : **-ied**) · stop → stopped et plan → planned (verbe court : on **double** la consonne) · play → played et walk → walked : **-ed** tout simple."},{"cle":{"type":"ordre","ids":["b","d","c","a"]},"explication":"**Did Lola study on Saturday?** On met *did* devant le sujet, et le verbe revient à la base : *study* (et non « studied »)."}]$ex$::jsonb),
  ('fbca82b1-9d7f-5da1-b5f3-ed6eaf7f9367'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une sortie au zoo, hier","competence":"comprendre-langue","situation":"Hier, Inès a visité le zoo. Elle avait préparé un programme sur un papier. Tom, son ami, lui écrit pour savoir comment s’est passée la journée, puis lui raconte la sienne.","documents":[{"id":"plan","type":"fiche","modele":"horaires","entete":"Inès’s plan","sousTitre":"Yesterday at the zoo","emoji":"🦁","teinte":"ambre","lignes":[{"texte":"10:00 – see the lions","valeur":"✓"},{"texte":"11:00 – eat a sandwich","valeur":"✓"},{"texte":"12:00 – take photos of the monkeys","valeur":"✓"},{"texte":"14:00 – buy a postcard","valeur":"✗","id":"z1"}],"pied":"✓ = fait · ✗ = pas fait (la boutique était fermée)"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","source":"Messages écrits pour l’exercice.","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Hi Tom! What did you do yesterday?"},{"qui":"Tom","texte":"We goed to the park, but I didn’t took my bike."}]}],"questions":[{"enonce":"Que raconte Inès sur ce qu’elle a fait à **11:00** ?","aide":"C’est passé (hier). « eat » est irrégulier : il ne prend pas -ed.","type":"choix","options":[{"id":"a","texte":"She will eat a sandwich."},{"id":"b","texte":"She eated a sandwich."},{"id":"c","texte":"She eats a sandwich."},{"id":"d","texte":"She ate a sandwich."}],"multiple":false},{"enonce":"Inès n’a pas fait tout ce qui était prévu. Remets les mots dans l’ordre pour dire ce qu’elle n’a **pas** fait.","aide":"Regarde la ligne marquée ✗. La négation au passé : sujet + didn’t + base verbale.","type":"ordre","items":[{"id":"a","texte":"a postcard"},{"id":"b","texte":"She"},{"id":"c","texte":"buy"},{"id":"d","texte":"didn’t"}]},{"enonce":"Tom a fait deux erreurs de prétérit dans son message. Touche les deux mots fautifs.","aide":"Un verbe irrégulier ne prend pas -ed, et après didn’t le verbe reste à la base.","type":"zone","document":"sms","multiple":true},{"enonce":"Corrige le message de Tom.","aide":"Premier trou : prétérit de go. Second trou : après didn’t, base verbale.","type":"trous","segments":["We ",0," to the park, but I didn’t ",1," my bike."],"banque":["take","goed","went","took"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"**She ate a sandwich.** Le prétérit irrégulier de *eat* est *ate*. « eated » n’existe pas, « eats » est au présent et « will eat » au futur."},{"cle":{"type":"ordre","ids":["b","d","c","a"]},"explication":"**She didn’t buy a postcard.** *didn’t* porte déjà le passé : le verbe reste à la base (*buy*, pas « bought »)."},{"cle":{"type":"zone","ids":["m8","m15"]},"explication":"**goed** est faux : go est irrégulier, son prétérit est *went*. **took** est faux après *didn’t* : le verbe revient à la base, *take*."},{"cle":{"type":"trous","trous":[["went"],["take"]]},"affichage":"went · take","explication":"We **went** to the park (go → went), but I didn’t **take** my bike (après *didn’t*, la base verbale)."}]$ex$::jsonb),
  ('1fa9acb6-b9d3-58e4-a5bb-1aee662876a6'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La liste de verbes de Mia","competence":"lire-tableau","situation":"Mia prépare son contrôle d’anglais. Elle a recopié ses verbes irréguliers dans un tableau à trois colonnes : la base, le prétérit et le participe passé.","documents":[{"id":"liste","type":"tableau","titre":"Mia’s list","colonnes":["Base","Past","Participle"],"lignes":[["go","went","gone"],["see","saw","seen"],["take","took","taken"],["put","put","put"],["buy","bought","bought"],["give","gave","given"],["think","thought","thought"],["find","found","found"]],"enteteLignes":true,"source":"Liste écrite pour l’exercice."}],"questions":[{"enonce":"Touche la case qui donne le **prétérit** du verbe *see*.","aide":"Trouve la ligne de *see*, puis la colonne « Past ».","type":"zone","document":"liste","multiple":false},{"enonce":"Quel verbe a les **trois formes identiques** dans le tableau ?","aide":"Cherche la ligne où le même mot est écrit trois fois.","type":"choix","options":[{"id":"a","texte":"take"},{"id":"b","texte":"go"},{"id":"c","texte":"give"},{"id":"d","texte":"put"}],"multiple":false},{"enonce":"Associe chaque verbe à son prétérit.","aide":"Relis les colonnes « Base » et « Past ». Deux prétérits se ressemblent : bought et thought.","type":"association","gauche":[{"id":"g0","texte":"buy"},{"id":"g1","texte":"think"},{"id":"g2","texte":"give"},{"id":"g3","texte":"find"}],"droite":[{"id":"d0","texte":"found"},{"id":"d1","texte":"thought"},{"id":"d2","texte":"bought"},{"id":"d3","texte":"gave"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Le prétérit de *see* est **saw** : c’est la case de la ligne *see*, colonne *Past*. Le participe passé (*seen*) est dans la colonne d’à côté."},{"cle":{"type":"choix","ids":["d"]},"explication":"**put — put — put** : ce verbe ne change jamais. *go*, *take* et *give* ont trois formes différentes."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g0":"d2","g2":"d3"}},"explication":"buy → **bought**, think → **thought**, give → **gave**, find → **found**. Ces formes ne se devinent pas, elles s’apprennent."}]$ex$::jsonb),
  ('1fa9acb6-b9d3-58e4-a5bb-1aee662876a6'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Les familles de verbes de Max","competence":"manier-langue","situation":"Max apprend ses verbes par familles, comme son professeur le lui conseille. Il a rangé huit verbes dans un tableau, puis il raconte son dimanche à Lena.","documents":[{"id":"famille","type":"tableau","titre":"Max’s verbs","colonnes":["Base","Past","Participle"],"lignes":[["cut","cut","cut"],["let","let","let"],["bring","brought","brought"],["teach","taught","taught"],["sing","sang","sung"],["swim","swam","swum"],["begin","began","begun"],["drink","drank","drunk"]],"enteteLignes":true,"source":"Liste écrite pour l’exercice."},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","source":"Messages écrits pour l’exercice.","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"What did you do on Sunday?"},{"qui":"Max","texte":"I swam in the lake, then I read a book and I drank an orange juice."}]}],"questions":[{"enonce":"Range les verbes de Max par famille, en regardant leurs trois formes dans le tableau.","aide":"Compare les trois colonnes de chaque ligne : tout pareil ? seulement les deux dernières ? voyelles i, a, u ?","type":"categories","categories":[{"id":"c0","texte":"Les trois formes sont pareilles"},{"id":"c1","texte":"Les deux dernières formes sont pareilles"},{"id":"c2","texte":"Schéma i → a → u"}],"items":[{"id":"i0","texte":"drink"},{"id":"i1","texte":"sing"},{"id":"i2","texte":"cut"},{"id":"i3","texte":"teach"},{"id":"i4","texte":"swim"},{"id":"i5","texte":"let"},{"id":"i6","texte":"begin"},{"id":"i7","texte":"bring"}]},{"enonce":"Max raconte son dimanche. Touche les **trois verbes au prétérit** dans son message.","aide":"Il raconte des choses passées : cherche ce qu’il a fait, et regarde le tableau pour reconnaître les formes.","type":"zone","document":"sms","multiple":true},{"enonce":"Dans « I **read** a book » (au passé), comment se prononce *read* ?","aide":"Le verbe *read* s’écrit pareil au présent et au passé, mais sa prononciation change.","type":"choix","options":[{"id":"a","texte":"Comme le mot « rid »"},{"id":"b","texte":"Comme le mot « reed »"},{"id":"c","texte":"Comme le mot « red »"},{"id":"d","texte":"Comme le mot « raid »"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c2","i1":"c2","i2":"c0","i3":"c1","i4":"c2","i5":"c0","i6":"c2","i7":"c1"}},"explication":"cut et let : **trois formes identiques**. bring et teach : **brought / taught** deux fois (les deux dernières pareilles). sing, swim, begin, drink : **i → a → u** (sing — sang — sung)."},{"cle":{"type":"zone","ids":["m7","m13","m18"]},"explication":"Max a dit **swam** (swim), **read** (read, écrit pareil au passé) et **drank** (drink)."},{"cle":{"type":"choix","ids":["c"]},"explication":"Au passé, *read* se prononce **/red/**, comme *red*. Au présent, il se prononce /riːd/. Seule l’oreille fait la différence."}]$ex$::jsonb),
  ('1fa9acb6-b9d3-58e4-a5bb-1aee662876a6'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le dimanche de Max, heure par heure","competence":"manier-langue","situation":"Max a noté ce qu’il voulait faire dimanche, heure par heure, avec des verbes de base. Pour écrire son récit, tu dois les mettre au prétérit : plusieurs sont irréguliers.","documents":[{"id":"dimanche","type":"fiche","modele":"horaires","entete":"Max’s Sunday","sousTitre":"What he did","emoji":"🗓️","teinte":"bleu","lignes":[{"texte":"get up","valeur":"7:00"},{"texte":"eat breakfast","valeur":"7:30"},{"texte":"put on his boots","valeur":"8:30","id":"z1"},{"texte":"write a postcard","valeur":"9:30"},{"texte":"buy some bread","valeur":"11:00"},{"texte":"read a comic","valeur":"12:30","id":"z2"}],"pied":"Programme imaginé pour l’exercice"}],"questions":[{"enonce":"Deux verbes de la liste s’écrivent **exactement pareil** au prétérit. Touche leurs lignes.","aide":"Pense à la famille « trois formes pareilles » et au piège de la prononciation.","type":"zone","document":"dimanche","multiple":true},{"enonce":"Remets ces phrases dans l’ordre de la journée de Max, d’après les heures.","aide":"Regarde les heures dans la fiche : 7:00, 7:30, 9:30, 11:00.","type":"ordre","items":[{"id":"a","texte":"He bought some bread."},{"id":"b","texte":"He ate breakfast."},{"id":"c","texte":"He wrote a postcard."},{"id":"d","texte":"He got up at seven."}]},{"enonce":"Complète avec le prétérit du verbe de la fiche.","aide":"Trouve la ligne de 11:00 : le verbe est *buy*. Son prétérit est irrégulier.","type":"trous","segments":["At eleven, Max ",0," some bread."],"banque":["buyed","bought","boughted","buy"]},{"enonce":"Associe chaque verbe de la fiche à son prétérit.","aide":"Ces quatre verbes sont irréguliers : pas de -ed.","type":"association","gauche":[{"id":"g0","texte":"get"},{"id":"g1","texte":"eat"},{"id":"g2","texte":"write"},{"id":"g3","texte":"buy"}],"droite":[{"id":"d0","texte":"ate"},{"id":"d1","texte":"bought"},{"id":"d2","texte":"got"},{"id":"d3","texte":"wrote"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"**put** (put — put — put) et **read** (read — read — read) ne changent pas d’écriture. Pour *read*, seule la prononciation change : /red/ au passé."},{"cle":{"type":"ordre","ids":["d","b","c","a"]},"explication":"Dans l’ordre : **got up** (7:00), **ate** breakfast (7:30), **wrote** a postcard (9:30), **bought** some bread (11:00). Quatre prétérits irréguliers."},{"cle":{"type":"trous","trous":[["bought"]]},"affichage":"bought","explication":"À 11:00, Max **bought** some bread : buy — bought — bought. « buyed » et « boughted » n’existent pas."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"get → **got**, eat → **ate**, write → **wrote**, buy → **bought**."}]$ex$::jsonb),
  ('f7b07e0b-039e-5987-98a6-0612beb468bc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les projets de Sam et d’Inès","competence":"comprendre-langue","situation":"Sam et Inès se racontent leurs projets. Certains sont pour demain, d’autres pour plus tard. Lis leurs messages pour trouver quand tout cela va se passer.","documents":[{"id":"projets","type":"dialogue","modele":"sms","titre":"Messages","source":"Messages écrits pour l’exercice.","participants":[{"nom":"Sam","emoji":"👦","cote":"gauche"},{"nom":"Inès","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Sam","texte":"Tomorrow I’m going to visit the zoo with Dad."},{"qui":"Inès","texte":"Great! Yesterday I stayed at home, but next week I’m going to see my cousins."},{"qui":"Sam","texte":"Nice! Tonight I’m going to watch a film."}]}],"questions":[{"enonce":"Touche les mots qui montrent que l’action est dans le **futur**.","aide":"Il y a un mot isolé dans la première phrase, deux mots à la suite dans la deuxième, et un dans la dernière. « Yesterday » est au passé.","type":"zone","document":"projets","multiple":true},{"enonce":"Complète la phrase avec la bonne forme de *be*.","aide":"Après « Sam » (il), quelle forme de *be* ? *be going to* = être + going to.","type":"trous","segments":["Sam ",0," going to visit the zoo."],"banque":["am","be","is","are"]},{"enonce":"Remets les mots dans l’ordre pour dire le projet d’Inès.","aide":"Sujet, puis be going to, puis la base verbale, puis ce qu’on voit.","type":"ordre","items":[{"id":"a","texte":"her cousins"},{"id":"b","texte":"Inès"},{"id":"c","texte":"is going to"},{"id":"d","texte":"see"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m16","m17","m25"]},"explication":"**Tomorrow**, **next week** et **tonight** annoncent le futur. *Yesterday* parle du passé."},{"cle":{"type":"trous","trous":[["is"]]},"affichage":"is","explication":"Sam **is** going to visit the zoo : *be going to* se forme avec **be** conjugué (ici *is* pour he/she/it)."},{"cle":{"type":"ordre","ids":["b","c","d","a"]},"explication":"**Inès is going to see her cousins.** Après *going to*, le verbe reste à la base : *see*."}]$ex$::jsonb),
  ('f7b07e0b-039e-5987-98a6-0612beb468bc'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Des nuages et un parapluie","competence":"manier-langue","situation":"Tom et Léa vont à l’école. Le ciel est sombre. Ils discutent et Léa trouve une solution.","documents":[{"id":"nuages","type":"dialogue","modele":"sms","titre":"À la sortie de l’école","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Look! Black clouds. It’s going to rain."},{"qui":"Tom","texte":"Oh no! I don’t have an umbrella."},{"qui":"Léa","texte":"Don’t worry. I’ll lend you mine."},{"qui":"Tom","texte":"Thanks! I promise I’ll give it back tomorrow."}]}],"questions":[{"enonce":"Deux fois, un personnage emploie la forme contractée de **will**. Touche-la.","aide":"La contraction de *will* s’écrit avec une apostrophe : ’ll.","type":"zone","document":"nuages","multiple":true},{"enonce":"Pourquoi Léa dit-elle « It’s **going to** rain » ?","aide":"Relis la phrase juste avant : Léa dit « Look! ». Que voit-elle ?","type":"choix","options":[{"id":"a","texte":"Parce qu’elle voit des nuages noirs."},{"id":"b","texte":"Parce que c’est l’horaire d’un train."},{"id":"c","texte":"Parce qu’elle fait une promesse."},{"id":"d","texte":"Parce que c’est son projet du week-end."}],"multiple":false},{"enonce":"Range ces phrases selon la forme du futur qu’elles utilisent.","aide":"Chaque phrase : est-ce une décision prise à l’instant, une promesse, une opinion (will) ? Ou un projet déjà décidé ou un indice visible (going to) ?","type":"categories","categories":[{"id":"c0","texte":"will (décision, promesse, opinion)"},{"id":"c1","texte":"be going to (projet, indice visible)"}],"items":[{"id":"i0","texte":"She is going to study medicine."},{"id":"i1","texte":"We are going to visit Rome this summer."},{"id":"i2","texte":"The phone is ringing: I’ll answer it!"},{"id":"i3","texte":"I think it will be sunny tomorrow."},{"id":"i4","texte":"I promise I will help you."},{"id":"i5","texte":"Look at that car! It is going to crash."}]},{"enonce":"Complète la promesse de Tom.","aide":"Une promesse se dit avec *will*. Regarde aussi le sujet « I » : quelles formes sont impossibles ?","type":"trous","segments":["I promise I ",0," give it back."],"banque":["will","are going to","is going to","going"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m23"]},"explication":"**I’ll** = *I will*. Léa décide à l’instant de prêter son parapluie ; Tom fait une promesse."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Be going to** s’emploie pour une prévision appuyée sur un **indice visible** : ici, les nuages noirs."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0","i5":"c1"}},"explication":"**will** : décision à l’instant (le téléphone sonne), opinion, promesse. **be going to** : projet déjà décidé (médecine, Rome) ou prévision fondée sur un indice (la voiture)."},{"cle":{"type":"trous","trous":[["will"]]},"affichage":"will","explication":"I promise I **will** give it back : *will* sert aux promesses, suivi de la base verbale. « I is going to » et « I are going to » sont faux."}]$ex$::jsonb),
  ('f7b07e0b-039e-5987-98a6-0612beb468bc'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une soirée au cinéma","competence":"comprendre-langue","situation":"Samedi, Tom, Léa et Max veulent aller au cinéma. Tu lis les horaires du cinéma, puis un petit message de Tom, pour choisir la bonne façon de parler du futur.","documents":[{"id":"cine","type":"fiche","modele":"horaires","entete":"Odeon Cinema","sousTitre":"Saturday","emoji":"🎬","teinte":"violet","lignes":[{"texte":"Space Cats","valeur":"4:30 pm","id":"z1"},{"texte":"Dragon Lake","valeur":"6:30 pm","id":"z2"},{"texte":"Night Zoo","valeur":"8:15 pm","id":"z3"}],"pied":"Horaires inventés pour l’exercice"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Messages","source":"Messages écrits pour l’exercice.","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Léa","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"I’m meeting Max outside the cinema at six."},{"qui":"Léa","texte":"OK! I’m going to see Dragon Lake."},{"qui":"Tom","texte":"Don’t be late!"}]}],"questions":[{"enonce":"Touche le film qui commence **le plus tard**.","aide":"Compare les heures : 4:30 pm, 6:30 pm, 8:15 pm.","type":"zone","document":"cine","multiple":false},{"enonce":"Pour parler d’un **horaire**, on utilise le présent simple. Complète.","aide":"Le sujet est « the film » (il) : le verbe prend un -s. « will starts » est impossible.","type":"trous","segments":["The film Dragon Lake ",0," at half past six."],"banque":["will starts","starts","start","starting"]},{"enonce":"Associe chaque situation à la phrase anglaise qui convient.","aide":"Relis le cours : horaire = présent simple · rendez-vous = BE + -ING · décision à l’instant et promesse = will · projet = going to.","type":"association","gauche":[{"id":"g0","texte":"Un horaire de cinéma"},{"id":"g1","texte":"Un rendez-vous organisé"},{"id":"g2","texte":"Une décision prise sur le moment"},{"id":"g3","texte":"Un projet déjà décidé"},{"id":"g4","texte":"Une promesse"}],"droite":[{"id":"d0","texte":"The film starts at 8."},{"id":"d1","texte":"I’m meeting Tom at 6."},{"id":"d2","texte":"I promise I will help you."},{"id":"d3","texte":"I’m going to learn the guitar."},{"id":"d4","texte":"The phone is ringing. I’ll answer it!"}]},{"enonce":"Tom dit à Léa : « Don’t be late! » Complète sa promesse.","aide":"C’est une promesse de ne PAS arriver en retard. La forme négative de *will* est irrégulière.","type":"trous","segments":["I promise I ",0," be late."],"banque":["isn’t","doesn’t","won’t","don’t"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**Night Zoo** commence à 8:15 pm, c’est le plus tardif."},{"cle":{"type":"trous","trous":[["starts"]]},"affichage":"starts","explication":"The film **starts** at half past six : on parle d’un horaire, donc **présent simple** (3e personne : -s)."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g4":"d2","g3":"d3","g2":"d4"}},"explication":"Horaire → **présent simple** (*starts*). Rendez-vous organisé → **BE + -ING** (*I’m meeting*). Décision à l’instant → **’ll** (le téléphone sonne). Projet déjà décidé → **be going to**. Promesse → **will**."},{"cle":{"type":"trous","trous":[["won t"]]},"affichage":"won’t","explication":"I promise I **won’t** be late : *won’t* est la contraction négative de *will not*. « don’t be late » est un ordre, pas une promesse avec *I*."}]$ex$::jsonb),
  ('e66a476a-caba-50e4-8ec3-d3dd433616c3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La nouvelle amie d’Emma","competence":"comprendre-langue","situation":"Emma parle à Tom de sa nouvelle amie, Kate. Elle utilise plusieurs petits mots pour ne pas répéter les noms : les pronoms.","documents":[{"id":"amie","type":"dialogue","modele":"sms","titre":"Messages","source":"Messages écrits pour l’exercice.","participants":[{"nom":"Emma","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Emma","texte":"Hi Tom! I have a new friend. My friend is Kate. She is from London. We play tennis together."},{"qui":"Tom","texte":"Nice! Do you like her?"}]}],"questions":[{"enonce":"Touche **tous les pronoms sujets** de ces messages (ceux qui sont devant le verbe).","aide":"Un pronom sujet est devant un verbe : I have · … is · … play · Do … like. « her » est un complément, on ne le touche pas.","type":"zone","document":"amie","multiple":true},{"enonce":"Associe chaque pronom sujet à son pronom complément.","aide":"Pense à « I know … » : on dit « I know him », « I know her »…","type":"association","gauche":[{"id":"g0","texte":"he"},{"id":"g1","texte":"she"},{"id":"g2","texte":"they"},{"id":"g3","texte":"we"}],"droite":[{"id":"d0","texte":"her"},{"id":"d1","texte":"them"},{"id":"d2","texte":"him"},{"id":"d3","texte":"us"}]},{"enonce":"Emma a une amie, Kate. Complète sa phrase.","aide":"Kate est une fille : quel pronom la remplace ? Et il est après le verbe : sujet ou complément ?","type":"trous","segments":["I like Kate. I like ",0,"."],"banque":["her","she","hers","him"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2","m11","m15","m21"]},"explication":"Les pronoms sujets sont **I**, **She**, **We** et **you** : chacun est juste devant son verbe. « her » est un pronom complément."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"he → **him**, she → **her**, they → **them**, we → **us**. Le complément se place après le verbe ou une préposition."},{"cle":{"type":"trous","trous":[["her"]]},"affichage":"her","explication":"I like **her** : *her* est le pronom complément de *she*, il est placé après le verbe."}]$ex$::jsonb),
  ('e66a476a-caba-50e4-8ec3-d3dd433616c3'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Il pleut, il est 7 heures","competence":"manier-langue","situation":"Léa téléphone à Max, le matin, avant d’aller à l’école. Elle lui parle de l’heure, du temps qu’il fait et de la distance. En anglais, ces phrases ont toujours un sujet.","documents":[{"id":"matin","type":"dialogue","modele":"sms","titre":"Un appel du matin","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Hi Max! It’s 7 o’clock. It’s raining, so take your coat."},{"qui":"Max","texte":"OK. Is it far to school?"},{"qui":"Léa","texte":"No, it’s 2 km. The buses are late, but they are nice and warm!"}]}],"questions":[{"enonce":"Dans toutes ces phrases, *it* est le sujet. Range-les selon ce qu’elles disent.","aide":"Pour chaque phrase, demande-toi : parle-t-elle de la pluie, d’une heure, ou d’un nombre de kilomètres ?","type":"categories","categories":[{"id":"c0","texte":"Le temps qu’il fait"},{"id":"c1","texte":"L’heure"},{"id":"c2","texte":"La distance"}],"items":[{"id":"i0","texte":"It’s snowing."},{"id":"i1","texte":"It’s half past eight."},{"id":"i2","texte":"It’s 5 km to the beach."},{"id":"i3","texte":"It’s 7 o’clock."},{"id":"i4","texte":"It’s 2 km."},{"id":"i5","texte":"It’s raining."}]},{"enonce":"Léa parle des bus. Touche le pronom qui remplace **« the buses »**.","aide":"Les bus sont plusieurs. Regarde la fin du dernier message de Léa.","type":"zone","document":"matin","multiple":false},{"enonce":"Complète la phrase avec le bon pronom sujet.","aide":"On parle d’une distance : il n’y a ni garçon, ni fille, ni pluriel.","type":"trous","segments":[0," is 2 km to the school."],"banque":["She","They","It","He"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c2","i3":"c1","i4":"c2","i5":"c0"}},"explication":"It’s raining et It’s snowing → **le temps**. It’s 7 o’clock et It’s half past eight → **l’heure**. It’s 2 km et It’s 5 km → **la distance**. En anglais, ces phrases ont toujours le sujet *it*."},{"cle":{"type":"zone","ids":["m26"]},"explication":"**they** remplace tous les pluriels : « the buses are late, but **they** are nice ». Ici *they* parle de choses, pas de personnes."},{"cle":{"type":"trous","trous":[["it"]]},"affichage":"It","explication":"**It** is 2 km : *it* est le pronom des distances (comme de l’heure et du temps)."}]$ex$::jsonb),
  ('e66a476a-caba-50e4-8ec3-d3dd433616c3'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le mail de Ben, plein d’erreurs","competence":"manier-langue","situation":"Ben, un élève de 6e, écrit à son correspondant. Son mail contient trois erreurs de pronoms. Tu aides à les trouver et à les corriger.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Ben’s email","source":"Mail écrit pour l’exercice.","blocs":["Hi! My name is Ben.","Me live in Leeds. I have two cousins, Ana and Joe. I often see they at the weekend.","My mum gives we cake and juice. It’s great!"]}],"questions":[{"enonce":"Touche les **trois pronoms fautifs** dans le mail de Ben.","aide":"Le sujet se met devant le verbe (I live), le complément après le verbe (see them, gives us). Cherche les pronoms mal choisis.","type":"zone","document":"mail","multiple":true},{"enonce":"Corrige les trois phrases de Ben.","aide":"Premier trou : sujet. Deuxième et troisième : compléments (après le verbe).","type":"trous","segments":[0," live in Leeds. I often see ",1," at the weekend. My mum gives ",2," cake."],"banque":["I","they","us","we","me","them"]},{"enonce":"Remets les mots dans l’ordre : la phrase doit garder l’ordre sujet – verbe – complément.","aide":"Qui fait l’action ? Quel verbe ? À qui ? Quoi ?","type":"ordre","items":[{"id":"a","texte":"sends"},{"id":"b","texte":"us"},{"id":"c","texte":"a postcard"},{"id":"d","texte":"Zoe"}]},{"enonce":"Quelle phrase est correcte pour dire l’heure ?","aide":"En anglais, le sujet ne peut jamais être omis. Quel pronom emploie-t-on pour l’heure ?","type":"choix","options":[{"id":"a","texte":"He is 3 o’clock."},{"id":"b","texte":"Is 3 o’clock."},{"id":"c","texte":"They are 3 o’clock."},{"id":"d","texte":"It is 3 o’clock."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m19","m26"]},"explication":"**Me** est un complément : le sujet est **I**. **they** est un sujet : après *see* on dit **them**. **we** est un sujet : après *gives* on dit **us**."},{"cle":{"type":"trous","trous":[["i"],["them"],["us"]]},"affichage":"I · them · us","explication":"**I** live (sujet) · I often see **them** (complément de *they*) · My mum gives **us** cake (complément de *we*)."},{"cle":{"type":"ordre","ids":["d","a","b","c"]},"explication":"**Zoe sends us a postcard.** Sujet (*Zoe*) → verbe (*sends*) → pronom complément (*us*) → ce qu’elle envoie."},{"cle":{"type":"choix","ids":["d"]},"explication":"**It is 3 o’clock.** On emploie *it* pour l’heure, comme pour le temps et la distance."}]$ex$::jsonb),
  ('b4426e48-7529-5c04-8715-4088b05f6888'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une interview pour le journal du collège","competence":"comprendre-langue","situation":"Sam rencontre Inès pour la première fois. Il lui pose trois questions pour écrire un article dans le journal du collège.","documents":[{"id":"interview","type":"dialogue","modele":"sms","titre":"The interview","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Sam","emoji":"👦","cote":"gauche"},{"nom":"Inès","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Sam","texte":"Hello! What is your name?"},{"qui":"Inès","texte":"I’m Inès."},{"qui":"Sam","texte":"Where do you live?"},{"qui":"Inès","texte":"In Lyon."},{"qui":"Sam","texte":"How old are you?"},{"qui":"Inès","texte":"I’m eleven."}]}],"questions":[{"enonce":"Touche les **mots interrogatifs** qui ouvrent les questions de Sam.","aide":"Ce sont les mots qui se placent tout au début d’une question : ils sont trois, un par question.","type":"zone","document":"interview","multiple":true},{"enonce":"Associe chaque question de Sam à la réponse d’Inès.","aide":"Relis le dialogue : chaque réponse suit sa question.","type":"association","gauche":[{"id":"g0","texte":"What is your name?"},{"id":"g1","texte":"Where do you live?"},{"id":"g2","texte":"How old are you?"}],"droite":[{"id":"d0","texte":"In Lyon."},{"id":"d1","texte":"I’m eleven."},{"id":"d2","texte":"I’m Inès."}]},{"enonce":"Remets les mots dans l’ordre pour reformer la question de Sam.","aide":"Mot interrogatif, puis auxiliaire, puis sujet, puis verbe.","type":"ordre","items":[{"id":"a","texte":"live?"},{"id":"b","texte":"do"},{"id":"c","texte":"Where"},{"id":"d","texte":"you"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m7","m13"]},"explication":"**What** (quoi, que), **Where** (où) et **How** (comment) ouvrent les trois questions de Sam."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"What is your name? → **I’m Inès.** · Where do you live? → **In Lyon.** · How old are you? → **I’m eleven.**"},{"cle":{"type":"ordre","ids":["c","b","d","a"]},"explication":"**Where do you live?** L’ordre est toujours : mot interrogatif → auxiliaire (*do*) → sujet (*you*) → verbe (*live*)."}]$ex$::jsonb),
  ('b4426e48-7529-5c04-8715-4088b05f6888'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La fiche de Sam, le correspondant","competence":"manier-langue","situation":"Ton professeur te donne la fiche de Sam, ton correspondant anglais. Tu dois préparer des questions pour lui écrire, puis comprendre comment on répond.","documents":[{"id":"fiche","type":"fiche","modele":"affiche","entete":"Sam’s card","sousTitre":"My correspondent","emoji":"🇬🇧","teinte":"bleu","lignes":[{"texte":"Name: Sam","id":"z1"},{"texte":"Age: 12","id":"z2"},{"texte":"Home: Leeds","id":"z3"},{"texte":"Hobby: swimming","id":"z4"},{"texte":"Pet: a cat","id":"z5"}],"pied":"Fiche imaginée pour l’exercice"}],"questions":[{"enonce":"Tu veux poser : « What is Sam’s **hobby**? » Touche la ligne de la fiche qui donne la réponse.","aide":"Hobby veut dire « loisir ».","type":"zone","document":"fiche","multiple":false},{"enonce":"Associe chaque information de la fiche à la question qui y répond.","aide":"Pense au mot interrogatif qui convient : où ? quel âge ? quoi ?","type":"association","gauche":[{"id":"g0","texte":"Leeds"},{"id":"g1","texte":"12"},{"id":"g2","texte":"swimming"},{"id":"g3","texte":"a cat"}],"droite":[{"id":"d0","texte":"How old is Sam?"},{"id":"d1","texte":"What is Sam’s hobby?"},{"id":"d2","texte":"What is Sam’s pet?"},{"id":"d3","texte":"Where does Sam live?"}]},{"enonce":"Complète cette question fermée (qui attend « oui » ou « non »).","aide":"Le verbe est *like* (ni be, ni modal) : on appelle *do*. Le sujet « Sam » = he : quelle forme ?","type":"trous","segments":[0," Sam like swimming?"],"banque":["Are","Is","Does","Do"]},{"enonce":"On te demande : « Does Sam live in London? » Quelle est la bonne **réponse courte** d’après la fiche ?","aide":"Sam habite à Leeds : la réponse est non. On reprend l’auxiliaire de la question.","type":"choix","options":[{"id":"a","texte":"No, he isn’t."},{"id":"b","texte":"No, he doesn’t."},{"id":"c","texte":"No, I don’t."},{"id":"d","texte":"No, he don’t."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"La réponse est sur la ligne **Hobby: swimming** : le loisir de Sam, c’est la natation."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Leeds → **Where** does Sam live? · 12 → **How old** is Sam? · swimming → **What** is Sam’s hobby? · a cat → **What** is Sam’s pet?"},{"cle":{"type":"trous","trous":[["does"]]},"affichage":"Does","explication":"**Does** Sam like swimming? Avec *like* on met *do* devant le sujet, et **does** à la 3e personne (he, she, it)."},{"cle":{"type":"choix","ids":["b"]},"explication":"**No, he doesn’t.** La question est faite avec *does* : la réponse courte reprend *does*, avec *he* (Sam)."}]$ex$::jsonb),
  ('b4426e48-7529-5c04-8715-4088b05f6888'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La sortie au zoo de Londres","competence":"manier-langue","situation":"La classe de Mrs Green prépare une sortie scolaire. Une affiche donne les informations, puis un message parle d’un sac trouvé. Pose les bonnes questions pour tout comprendre.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"School trip","sousTitre":"London Zoo","emoji":"🦒","teinte":"vert","lignes":[{"texte":"Date: Friday"},{"texte":"Price: £5 per student"},{"texte":"Students: 25"},{"texte":"Distance: 3 km from school"},{"texte":"With us: Mrs Green"}],"pied":"Affiche imaginée pour l’exercice"},{"id":"sac","type":"dialogue","modele":"sms","titre":"À la sortie du bus","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Look! A red bag on the seat."},{"qui":"Tom","texte":"It’s Lola’s."}]}],"questions":[{"enonce":"Associe chaque information de l’affiche à la question qui y répond.","aide":"Un prix : *how much*. Un nombre : *how many*. Une distance : *how far*. Un jour : *when*.","type":"association","gauche":[{"id":"g0","texte":"£5"},{"id":"g1","texte":"25"},{"id":"g2","texte":"3 km"},{"id":"g3","texte":"Friday"}],"droite":[{"id":"d0","texte":"When is the trip?"},{"id":"d1","texte":"How far is the zoo?"},{"id":"d2","texte":"How much is the trip?"},{"id":"d3","texte":"How many students are there?"}]},{"enonce":"Remets les mots dans l’ordre pour poser la question sur le nombre d’élèves.","aide":"*how many* + nom, puis l’auxiliaire, puis le sujet.","type":"ordre","items":[{"id":"a","texte":"students"},{"id":"b","texte":"How many"},{"id":"c","texte":"there?"},{"id":"d","texte":"are"}]},{"enonce":"Mrs Green va avec la classe. Quelle est la bonne question pour demander **qui** y va (Mrs Green est le sujet) ?","aide":"Quand le mot interrogatif est lui-même le sujet, on n’ajoute pas d’auxiliaire.","type":"choix","options":[{"id":"a","texte":"Who goes does with the class?"},{"id":"b","texte":"Who does go with the class?"},{"id":"c","texte":"Who goes with the class?"},{"id":"d","texte":"Who do goes with the class?"}],"multiple":false},{"enonce":"Léa montre le sac. Écris le mot interrogatif qui manque : « ___ bag is this? — It’s Lola’s. »","aide":"Le mot qui demande « à qui est… ? » commence par w et finit par -se.","type":"texte","placeholder":"Un mot"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"£5 → **How much**… ? · 25 élèves → **How many**… ? · 3 km → **How far**… ? · Friday → **When**… ?"},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"**How many students are there?** On met *how many* + le nom en tête, puis *are*, puis *there*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Who goes with the class?** *Who* est le sujet : pas de *do*, et le verbe prend le -s de la 3e personne."},{"cle":{"type":"texte","acceptes":["whose"]},"affichage":"Whose","explication":"**Whose** bag is this? signifie « À qui est ce sac ? ». La réponse est *It’s Lola’s*."}]$ex$::jsonb),
  ('1ece81b2-1c56-59a7-a6f7-5d9ac25ffc95'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Ce que Max aime et n’aime pas","competence":"comprendre-langue","situation":"Lola présente Max à ses amis anglais. Elle dit ce qu’il aime, ce qu’il sait faire… et ce qu’il n’aime pas et ne sait pas faire.","documents":[{"id":"max","type":"texte","genre":"recit","titre":"About Max","source":"Texte écrit pour l’exercice.","blocs":["Max loves pizza. He likes football too, but he doesn’t like fish. He can swim, but he can’t ride a bike. His sisters don’t play football."]}],"questions":[{"enonce":"Touche les **trois formes négatives** du texte.","aide":"Ce sont des mots contractés qui finissent par n’t.","type":"zone","document":"max","multiple":true},{"enonce":"Complète la phrase sur les sœurs de Max.","aide":"Le sujet est pluriel (they). Le verbe *play* n’est pas *be*.","type":"trous","segments":["Max’s sisters ",0," play football."],"banque":["don’t","doesn’t","isn’t","aren’t"]},{"enonce":"Associe chaque phrase affirmative à sa négation contractée.","aide":"On ajoute *not* après l’auxiliaire, puis on contracte : is not → isn’t.","type":"association","gauche":[{"id":"g0","texte":"he is"},{"id":"g1","texte":"they are"},{"id":"g2","texte":"I can"},{"id":"g3","texte":"we do"}],"droite":[{"id":"d0","texte":"we don’t"},{"id":"d1","texte":"I can’t"},{"id":"d2","texte":"they aren’t"},{"id":"d3","texte":"he isn’t"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9","m17","m23"]},"explication":"**doesn’t**, **can’t** et **don’t** sont les trois négations : elles disent ce que Max ne fait pas, ne peut pas faire, et ce que ses sœurs ne font pas."},{"cle":{"type":"trous","trous":[["don t"]]},"affichage":"don’t","explication":"Max’s sisters **don’t** play football : avec *they*, la négation de *play* est *don’t* (et *doesn’t* pour he, she, it)."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"he is → **he isn’t** · they are → **they aren’t** · I can → **I can’t** · we do → **we don’t**."}]$ex$::jsonb),
  ('1ece81b2-1c56-59a7-a6f7-5d9ac25ffc95'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un cinéma presque vide","competence":"manier-langue","situation":"Tom et Léa sont allés au cinéma très tôt le matin. Tom parle anglais avec un ami, mais il fait deux erreurs de négation typiquement françaises.","documents":[{"id":"cine","type":"dialogue","modele":"sms","titre":"Au cinéma","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Léa","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Oh! I don’t see nothing on the screen!"},{"qui":"Léa","texte":"That’s because there isn’t nobody in the projection room!"}]}],"questions":[{"enonce":"Dans chaque réplique, un mot cause une **double négation**. Touche ces deux mots.","aide":"Ces mots sont déjà négatifs ; ils ne vont pas avec *n’t*.","type":"zone","document":"cine","multiple":true},{"enonce":"Comment Tom devrait-il dire « Je ne vois rien » ?","aide":"Il faut une seule négation. Avec *don’t*, on emploie *anything* ; avec *nothing*, pas de *don’t*.","type":"choix","options":[{"id":"a","texte":"I see not anything."},{"id":"b","texte":"I don’t see anything."},{"id":"c","texte":"I not see anything."},{"id":"d","texte":"I don’t see nothing."}],"multiple":false},{"enonce":"Complète la phrase avec le mot qui convient devant un nom.","aide":"Devant un nom (popcorn), un mot négatif simple. « nothing » et « nobody » sont des pronoms, ils s’emploient seuls.","type":"trous","segments":["There is ",0," popcorn in the bag: it’s empty."],"banque":["not","nobody","no","nothing"]},{"enonce":"Remets les mots dans l’ordre pour dire que Léa ne mange jamais de pop-corn.","aide":"*never* est déjà négatif : pas de *don’t*. Il se place avant le verbe.","type":"ordre","items":[{"id":"a","texte":"eat"},{"id":"b","texte":"popcorn"},{"id":"c","texte":"I"},{"id":"d","texte":"never"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m12"]},"explication":"**nothing** et **nobody** sont déjà négatifs. Avec *don’t* / *isn’t*, la phrase aurait deux négations, ce qui est faux en anglais."},{"cle":{"type":"choix","ids":["b"]},"explication":"**I don’t see anything.** (ou « I see nothing »). On ne cumule jamais deux négations : « I don’t see nothing » dirait « je vois quelque chose »."},{"cle":{"type":"trous","trous":[["no"]]},"affichage":"no","explication":"There is **no** popcorn : *no* se place devant un nom. On peut aussi dire *There isn’t any popcorn*."},{"cle":{"type":"ordre","ids":["c","d","a","b"]},"explication":"**I never eat popcorn.** *never* se place avant le verbe, sans *don’t* (« I don’t never eat » est faux)."}]$ex$::jsonb),
  ('1ece81b2-1c56-59a7-a6f7-5d9ac25ffc95'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Zoe et Ben : qui sait faire quoi ?","competence":"lire-tableau","situation":"Zoe et son frère Ben comparent ce qu’ils savent faire. Un tableau résume tout ; tu écris ensuite des phrases négatives pour décrire ce que l’un ou l’autre ne fait pas.","documents":[{"id":"tableau","type":"tableau","titre":"What can Zoe and Ben do?","colonnes":["Activity","Zoe","Ben"],"lignes":[["swim","✓","✗"],["play the piano","✗","✓"],["ride a horse","✗","✗"],["speak Spanish","✓","✓"]],"enteteLignes":true,"source":"Tableau inventé pour l’exercice. ✓ = sait le faire, ✗ = ne sait pas."}],"questions":[{"enonce":"Touche la case qui prouve que **Ben ne sait pas nager**.","aide":"Trouve la ligne *swim*, puis la colonne de Ben.","type":"zone","document":"tableau","multiple":false},{"enonce":"Quelle phrase est **vraie** d’après le tableau ?","aide":"Vérifie chaque phrase dans le tableau, ligne par ligne.","type":"choix","options":[{"id":"a","texte":"Zoe can ride a horse."},{"id":"b","texte":"Ben can’t swim, but Zoe can."},{"id":"c","texte":"Ben can’t play the piano."},{"id":"d","texte":"Zoe can’t speak Spanish."}],"multiple":false},{"enonce":"Complète les phrases avec la bonne négation.","aide":"Regarde le repère de temps : « Last Sunday » (passé), « Every Saturday » (habitude). Puis un modal, puis *be* au pluriel.","type":"trous","segments":["Last Sunday, Zoe ",0," go to the pool. Every Saturday, Ben ",1," go to the pool. Ben ",2," swim. The two children ",3," happy."],"banque":["don’t","doesn’t","didn’t","aren’t","can’t","isn’t"]},{"enonce":"Remets les mots dans l’ordre pour écrire une phrase vraie d’après le tableau.","aide":"Sujet, puis modal négatif, puis verbe à la base.","type":"ordre","items":[{"id":"a","texte":"a horse"},{"id":"b","texte":"can’t"},{"id":"c","texte":"Zoe"},{"id":"d","texte":"ride"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"La croix de Ben sur la ligne *swim* le prouve : **Ben can’t swim**."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Ben can’t swim, but Zoe can** est vraie. Les autres sont fausses : Zoe ne sait pas monter à cheval, Ben sait jouer du piano et Zoe parle espagnol."},{"cle":{"type":"trous","trous":[["didn t"],["doesn t"],["can t"],["aren t"]]},"affichage":"didn’t · doesn’t · can’t · aren’t","explication":"Zoe **didn’t** go (passé : *didn’t* + base) · Ben **doesn’t** go (habitude, il) · Ben **can’t** swim (modal) · the two children **aren’t** happy (*be*, pluriel)."},{"cle":{"type":"ordre","ids":["c","b","d","a"]},"explication":"**Zoe can’t ride a horse.** Le modal *can’t* est suivi de la base verbale, sans *to*."}]$ex$::jsonb),
  ('bd594123-7056-5cf4-a4d4-d85413e58d59'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le règlement de la bibliothèque","competence":"comprendre-langue","situation":"Tu visites la bibliothèque d’un collège anglais. Un panneau à l’entrée donne le règlement. Les consignes sont à l’impératif.","documents":[{"id":"panneau","type":"fiche","modele":"panneau","entete":"Library rules","emoji":"📚","teinte":"violet","lignes":[{"texte":"Be quiet.","id":"z1"},{"texte":"Don’t run.","id":"z2"},{"texte":"Don’t eat here.","id":"z3"},{"texte":"Put your books back.","id":"z4"},{"texte":"Don’t shout.","id":"z5"}],"pied":"Panneau imaginé pour l’exercice"}],"questions":[{"enonce":"Touche **toutes les consignes qui interdisent** quelque chose.","aide":"L’interdiction commence par *Don’t*.","type":"zone","document":"panneau","multiple":true},{"enonce":"Associe chaque consigne à sa traduction.","aide":"L’impératif est la base verbale, sans sujet.","type":"association","gauche":[{"id":"g0","texte":"Sit down."},{"id":"g1","texte":"Open your book."},{"id":"g2","texte":"Listen."},{"id":"g3","texte":"Don’t talk."}],"droite":[{"id":"d0","texte":"Ne parle pas."},{"id":"d1","texte":"Écoute."},{"id":"d2","texte":"Ouvre ton livre."},{"id":"d3","texte":"Assieds-toi."}]},{"enonce":"Complète la consigne pour dire à un élève de ne pas arriver en retard.","aide":"Même avec le verbe *be*, la négation de l’impératif se fait avec *don’t*.","type":"trous","segments":[0," be late!"],"banque":["Not","Doesn’t","Don’t","No"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2","z3","z5"]},"explication":"**Don’t run**, **Don’t eat here** et **Don’t shout** sont des interdictions : *Don’t* + base verbale."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"Sit down → **Assieds-toi** · Open your book → **Ouvre ton livre** · Listen → **Écoute** · Don’t talk → **Ne parle pas**."},{"cle":{"type":"trous","trous":[["don t"]]},"affichage":"Don’t","explication":"**Don’t** be late! : avec *be* aussi, on emploie *don’t*. C’est le seul cas où *be* passe par DO."}]$ex$::jsonb),
  ('bd594123-7056-5cf4-a4d4-d85413e58d59'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"La recette des pancakes","competence":"comprendre-langue","situation":"Léa prépare des pancakes avec sa correspondante anglaise. La recette est écrite en anglais : toutes les phrases sont à l’impératif.","documents":[{"id":"recette","type":"fiche","modele":"recette","entete":"Easy pancakes","emoji":"🥞","teinte":"ambre","lignes":[{"texte":"Mix the flour and the eggs.","id":"z1"},{"texte":"Add the milk slowly.","id":"z2"},{"texte":"Don’t stop mixing!","id":"z3"},{"texte":"Heat the pan.","id":"z4"},{"texte":"Pour the mixture in the pan.","id":"z5"},{"texte":"Don’t touch the hot pan!","id":"z6"}],"pied":"Recette écrite pour l’exercice"}],"questions":[{"enonce":"Touche les **deux consignes négatives** de la recette.","aide":"Cherche *Don’t*.","type":"zone","document":"recette","multiple":true},{"enonce":"Léa dit à son amie la première étape de la recette. Complète.","aide":"L’impératif est la base verbale, sans -s ni -ing. Relis la première ligne de la recette.","type":"trous","segments":[0," the flour and the eggs, please."],"banque":["Mix","Mixed","Mixing","Mixes"]},{"enonce":"Range ces phrases selon ce qu’elles expriment.","aide":"*Let’s* propose une action collective. *Don’t* interdit. Le reste est un ordre simple.","type":"categories","categories":[{"id":"c0","texte":"Un ordre"},{"id":"c1","texte":"Une proposition à faire ensemble"},{"id":"c2","texte":"Une interdiction"}],"items":[{"id":"i0","texte":"Don’t touch the oven!"},{"id":"i1","texte":"Wash your hands."},{"id":"i2","texte":"Let’s go to the shop."},{"id":"i3","texte":"Let’s make pancakes!"},{"id":"i4","texte":"Don’t be late."},{"id":"i5","texte":"Open the window."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3","z6"]},"explication":"**Don’t stop mixing!** (ne t’arrête pas de mélanger) et **Don’t touch the hot pan!** (ne touche pas la poêle chaude)."},{"cle":{"type":"trous","trous":[["mix"]]},"affichage":"Mix","explication":"**Mix** the flour and the eggs, please : la base verbale, sans sujet. *please* adoucit l’ordre."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1","i3":"c1","i4":"c2","i5":"c0"}},"explication":"Open the window et Wash your hands : un **ordre** (base verbale). Let’s make… et Let’s go… : une **proposition à faire ensemble**. Don’t touch… et Don’t be late : une **interdiction**."}]$ex$::jsonb),
  ('bd594123-7056-5cf4-a4d4-d85413e58d59'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le stylo oublié","competence":"manier-langue","situation":"Tom a oublié son stylo à la maison. Il demande à Léa de lui en prêter un. Observe comment ils s’expriment poliment.","documents":[{"id":"stylo","type":"dialogue","modele":"sms","titre":"En classe","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Léa","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Could you lend me a pen, please?"},{"qui":"Léa","texte":"Sorry, I don’t have one. Where is yours?"},{"qui":"Tom","texte":"At home. Oh, forget it! I’ll ask Sam."},{"qui":"Léa","texte":"OK. Don’t forget your pen next time!"}]}],"questions":[{"enonce":"Quand Tom dit « **Forget it!** », que veut-il dire ?","aide":"Ne confonds pas avec « Don’t forget » : le contexte (il va demander à Sam) aide.","type":"choix","options":[{"id":"a","texte":"N’oublie pas !"},{"id":"b","texte":"Ne le dis à personne."},{"id":"c","texte":"Oublie ton stylo à la maison."},{"id":"d","texte":"Laisse tomber !"}],"multiple":false},{"enonce":"Tom demande poliment. Touche les **trois mots** qui adoucissent sa demande.","aide":"Une petite question avec un modal, et le mot magique.","type":"zone","document":"stylo","multiple":true},{"enonce":"Léa propose à Tom de ne pas se disputer. Remets les mots dans l’ordre.","aide":"*Let’s* + base verbale pour proposer ; *not* se place juste après *Let’s*.","type":"ordre","items":[{"id":"a","texte":"again"},{"id":"b","texte":"not"},{"id":"c","texte":"argue"},{"id":"d","texte":"Let’s"}]},{"enonce":"Associe chaque phrase française à sa traduction anglaise.","aide":"Un seul verbe, *forget*, sert dans deux phrases de sens opposé : ne les mélange pas.","type":"association","gauche":[{"id":"g0","texte":"Ne cours pas !"},{"id":"g1","texte":"Allons-y !"},{"id":"g2","texte":"N’oublie pas !"},{"id":"g3","texte":"Laisse tomber !"},{"id":"g4","texte":"Assieds-toi, s’il te plaît."}],"droite":[{"id":"d0","texte":"Don’t run!"},{"id":"d1","texte":"Forget it!"},{"id":"d2","texte":"Sit down, please."},{"id":"d3","texte":"Let’s go!"},{"id":"d4","texte":"Don’t forget!"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"**Forget it!** = « Laisse tomber ! ». Tom renonce à demander à Léa. « Don’t forget » veut dire l’inverse : « N’oublie pas »."},{"cle":{"type":"zone","ids":["m0","m1","m6"]},"explication":"**Could you … please** : la question modale *Could you…?* et le mot **please** adoucissent la demande, qui sinon serait un ordre direct."},{"cle":{"type":"ordre","ids":["d","b","c","a"]},"explication":"**Let’s not argue again.** *Let’s* (= let us) propose une action commune ; la négation se fait avec *not* après *Let’s*."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g4":"d2","g1":"d3","g2":"d4"}},"explication":"Ne cours pas → **Don’t run!** · Allons-y → **Let’s go!** · N’oublie pas → **Don’t forget!** · Laisse tomber → **Forget it!** · s’il te plaît → **please**."}]$ex$::jsonb),
  ('139927eb-fa01-5665-b1d6-872ead8f30cd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les animaux les plus rapides","competence":"lire-tableau","situation":"Dans un livre sur les animaux, Inès lit un tableau qui compare la vitesse maximale de quatre animaux. Elle prépare des phrases pour sa présentation en anglais.","documents":[{"id":"vitesses","type":"tableau","titre":"Animal speeds","colonnes":["Animal","Speed (km/h)"],"lignes":[["cheetah",110],["lion",80],["horse",70],["dog",60]],"enteteLignes":true,"source":"Chiffres arrondis, pour l’exercice."}],"questions":[{"enonce":"Touche la **vitesse de l’animal le plus rapide**.","aide":"Cherche le plus grand nombre de la colonne.","type":"zone","document":"vitesses","multiple":false},{"enonce":"Complète les deux phrases avec les bonnes formes de *fast*.","aide":"*fast* est un adjectif court : -er than, the -est. Pas de *more* avec un adjectif court.","type":"trous","segments":["The cheetah is ",0," than the lion. It is the ",1," animal in the table."],"banque":["more fast","most fast","fastest","faster"]},{"enonce":"Quelle phrase est **vraie** d’après le tableau ?","aide":"Compare les nombres : 70 contre 60, puis les autres paires.","type":"choix","options":[{"id":"a","texte":"The lion is slower than the dog."},{"id":"b","texte":"The horse is the fastest animal."},{"id":"c","texte":"The horse is faster than the dog."},{"id":"d","texte":"The dog is faster than the lion."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Le guépard (*cheetah*) court à **110 km/h** : c’est la plus grande vitesse, donc l’animal *the fastest*."},{"cle":{"type":"trous","trous":[["faster"],["fastest"]]},"affichage":"faster · fastest","explication":"The cheetah is **faster** than the lion (110 > 80) et c’est **the fastest** animal du tableau."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le cheval (70) est plus rapide que le chien (60) : **The horse is faster than the dog.** Les autres phrases sont fausses."}]$ex$::jsonb),
  ('139927eb-fa01-5665-b1d6-872ead8f30cd'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre animaux du zoo","competence":"lire-tableau","situation":"Au zoo, Léa compare la taille et l’âge de quatre animaux d’après un panneau. Elle utilise les comparatifs et les superlatifs pour décrire ce qu’elle voit.","documents":[{"id":"zoo","type":"tableau","titre":"Zoo information board","colonnes":["Animal","Height (cm)","Age (years)"],"lignes":[["giraffe",500,20],["elephant",300,60],["zebra",130,25],["lion",120,15]],"enteteLignes":true,"source":"Chiffres arrondis, inventés pour l’exercice."}],"questions":[{"enonce":"Touche l’**âge de l’animal le plus âgé** (*the oldest*).","aide":"Regarde la colonne « Age » et cherche le plus grand nombre.","type":"zone","document":"zoo","multiple":false},{"enonce":"Associe chaque adjectif à son comparatif.","aide":"Surveille l’orthographe : on double, on remplace y par i, on n’ajoute que -r, ou c’est irrégulier.","type":"association","gauche":[{"id":"g0","texte":"big"},{"id":"g1","texte":"happy"},{"id":"g2","texte":"nice"},{"id":"g3","texte":"good"}],"droite":[{"id":"d0","texte":"bigger"},{"id":"d1","texte":"better"},{"id":"d2","texte":"happier"},{"id":"d3","texte":"nicer"}]},{"enonce":"Compare la girafe et l’éléphant.","aide":"*tall* est court : on ajoute -er. Et il y a « than » : c’est un comparatif.","type":"trous","segments":["The giraffe is ",0," than the elephant."],"banque":["taller","tall","more tall","tallest"]},{"enonce":"Quelle phrase exprime correctement que le lion est **moins grand** que le zèbre ?","aide":"Compare 120 cm et 130 cm. Le lion est-il aussi grand ? Plus grand ?","type":"choix","options":[{"id":"a","texte":"The lion is the tallest."},{"id":"b","texte":"The lion is taller than the zebra."},{"id":"c","texte":"The lion is as tall as the zebra."},{"id":"d","texte":"The lion is not as tall as the zebra."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"L’éléphant a **60 ans** : c’est lui, *the oldest*."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"big → **bigger** (on double le g) · happy → **happier** (y devient i) · nice → **nicer** (seulement -r) · good → **better** (irrégulier)."},{"cle":{"type":"trous","trous":[["taller"]]},"affichage":"taller","explication":"The giraffe is **taller** than the elephant (500 cm contre 300 cm). On ne dit pas « more tall » : un adjectif court prend -er."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le lion (120 cm) est plus petit que le zèbre (130 cm) : **The lion is not as tall as the zebra.** (« pas aussi grand que »)."}]$ex$::jsonb),
  ('139927eb-fa01-5665-b1d6-872ead8f30cd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quel camp de vacances choisir ?","competence":"raisonner","situation":"Mia et ses parents hésitent entre trois camps de vacances. Un tableau donne le prix, la durée et une note d’amusement. Tu l’aides à comparer en anglais.","documents":[{"id":"camps","type":"tableau","titre":"Three holiday camps","colonnes":["Camp","Price (£)","Days","Fun score (/10)"],"lignes":[["Camp Sun",200,5,9],["Camp Sea",300,4,7],["Camp Hill",150,7,6]],"enteteLignes":true,"source":"Données inventées pour l’exercice."}],"questions":[{"enonce":"Touche le **prix du camp le plus cher**.","aide":"Regarde la colonne « Price » et trouve le plus grand nombre.","type":"zone","document":"camps","multiple":false},{"enonce":"Compare les prix. « expensive » est un adjectif long ; « cheap » est court.","aide":"Premier trou : adjectif long = *more … than*. Second trou : superlatif de *cheap* (court) = *the …-est*.","type":"trous","segments":["Camp Sea is ",0," than Camp Hill. Camp Hill is the ",1," camp."],"banque":["expensiver","most expensive","more expensive","cheaper","more cheap","cheapest"]},{"enonce":"Mia regarde la note d’amusement. Quelle phrase est **vraie** ?","aide":"*good → better → the best*, *bad → worse → the worst*. Compare 9, 7 et 6.","type":"choix","options":[{"id":"a","texte":"Camp Sun is worse than Camp Hill."},{"id":"b","texte":"Camp Sea is better than Camp Sun."},{"id":"c","texte":"Camp Hill is the best camp."},{"id":"d","texte":"Camp Sun is better than Camp Sea."}],"multiple":false},{"enonce":"Associe chaque adjectif à son superlatif.","aide":"Deux adjectifs sont irréguliers ; un est long (*the most*) ; un est court en -y (-y → -iest).","type":"association","gauche":[{"id":"g0","texte":"good"},{"id":"g1","texte":"bad"},{"id":"g2","texte":"interesting"},{"id":"g3","texte":"happy"}],"droite":[{"id":"d0","texte":"the happiest"},{"id":"d1","texte":"the most interesting"},{"id":"d2","texte":"the best"},{"id":"d3","texte":"the worst"}]},{"enonce":"Remets les mots dans l’ordre pour comparer les prix de Camp Hill et de Camp Sun.","aide":"Camp Hill coûte 150, Camp Sun coûte 200. *cheap* est un adjectif court.","type":"ordre","items":[{"id":"a","texte":"than Camp Sun"},{"id":"b","texte":"cheaper"},{"id":"c","texte":"Camp Hill"},{"id":"d","texte":"is"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Camp Sea coûte **£300** : c’est le camp *the most expensive*."},{"cle":{"type":"trous","trous":[["more expensive"],["cheapest"]]},"affichage":"more expensive · cheapest","explication":"Camp Sea is **more expensive** than Camp Hill (adjectif long : *more*) et Camp Hill est **the cheapest** (adjectif court : *-est*)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Camp Sun a 9/10, Camp Sea 7/10 : **Camp Sun is better than Camp Sea.** Le meilleur camp est Camp Sun, pas Camp Hill."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"good → **the best** · bad → **the worst** · interesting (long) → **the most interesting** · happy → **the happiest** (y devient i)."},{"cle":{"type":"ordre","ids":["c","d","b","a"]},"explication":"**Camp Hill is cheaper than Camp Sun.** (150 < 200). On ajoute -er à *cheap*, puis *than*."}]$ex$::jsonb),
  ('5a4bc8ef-ec15-5356-af90-cb8ef5afcf17'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le cercle de couleurs de Léna","competence":"observer-schema","situation":"Léna prépare ses tubes de gouache avant de peindre une affiche pour la fête du collège. Elle les range autour d’un cercle chromatique pour s’y retrouver.","documents":[{"id":"roue","type":"schema","titre":"Le cercle chromatique","largeur":320,"hauteur":250,"elements":[{"forme":"cercle","cx":160,"cy":47,"r":24,"teinte":"jaune","motif":"plein","id":"z1","zone":true},{"forme":"texte","x":160,"y":17,"texte":"Jaune","ancre":"milieu","gras":true},{"forme":"cercle","cx":228,"cy":86,"r":24,"teinte":"ambre","motif":"plein","id":"z2","zone":true},{"forme":"texte","x":258,"y":90,"texte":"Orange","ancre":"debut","gras":true},{"forme":"cercle","cx":228,"cy":164,"r":24,"teinte":"rose","motif":"plein","id":"z3","zone":true},{"forme":"texte","x":258,"y":168,"texte":"Magenta","ancre":"debut","gras":true},{"forme":"cercle","cx":160,"cy":203,"r":24,"teinte":"violet","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":160,"y":242,"texte":"Violet","ancre":"milieu","gras":true},{"forme":"cercle","cx":92,"cy":164,"r":24,"teinte":"ciel","motif":"plein","id":"z5","zone":true},{"forme":"texte","x":62,"y":168,"texte":"Cyan","ancre":"fin","gras":true},{"forme":"cercle","cx":92,"cy":86,"r":24,"teinte":"vert","motif":"plein","id":"z6","zone":true},{"forme":"texte","x":62,"y":90,"texte":"Vert","ancre":"fin","gras":true}],"source":"Cercle à six couleurs dessiné pour l’exercice"}],"questions":[{"enonce":"Touche les **trois couleurs primaires** du cercle.","aide":"Les primaires sont celles qu’aucun mélange ne permet d’obtenir : elles servent à fabriquer toutes les autres.","type":"zone","document":"roue","multiple":true},{"enonce":"Touche la couleur **complémentaire du jaune**.","aide":"Une couleur complémentaire se trouve exactement en face, de l’autre côté du cercle.","type":"zone","document":"roue","multiple":false},{"enonce":"Quelle couleur Léna obtient-elle en mélangeant ces deux primaires ?","aide":"Regarde, sur le cercle, la couleur secondaire qui se trouve entre les deux primaires.","type":"association","gauche":[{"id":"g0","texte":"Jaune + cyan"},{"id":"g1","texte":"Jaune + magenta"},{"id":"g2","texte":"Magenta + cyan"}],"droite":[{"id":"d0","texte":"Orange"},{"id":"d1","texte":"Violet"},{"id":"d2","texte":"Vert"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z3","z5"]},"explication":"Les primaires sont **magenta, cyan et jaune**. Vert, orange et violet sont des secondaires : chacun naît du mélange de deux primaires."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Le **violet** est en face du jaune : ces deux couleurs sont complémentaires. Posées côte à côte, elles se renforcent."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"Une secondaire est le mélange de **deux primaires** voisines : jaune + cyan donne du **vert**, jaune + magenta de l’**orange**, magenta + cyan du **violet**."}]$ex$::jsonb),
  ('5a4bc8ef-ec15-5356-af90-cb8ef5afcf17'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le paysage qui avance et qui recule","competence":"analyser-document","situation":"Sacha hésite entre deux versions de son petit tableau : un carré posé sur un fond. Il veut que le carré semble venir vers le spectateur, sans tracer aucune ligne de perspective.","documents":[{"id":"cadres","type":"schema","titre":"Deux essais de Sacha","largeur":320,"hauteur":230,"elements":[{"forme":"rect","x":20,"y":30,"l":130,"h":140,"teinte":"bleu","motif":"plein","id":"z1"},{"forme":"rect","x":60,"y":75,"l":50,"h":50,"teinte":"ambre","motif":"plein","id":"z2","zone":true},{"forme":"rect","x":170,"y":30,"l":130,"h":140,"teinte":"ambre","motif":"plein","id":"z3"},{"forme":"rect","x":210,"y":75,"l":50,"h":50,"teinte":"bleu","motif":"plein","id":"z4","zone":true},{"forme":"texte","x":85,"y":195,"texte":"Essai 1","ancre":"milieu","gras":true},{"forme":"texte","x":235,"y":195,"texte":"Essai 2","ancre":"milieu","gras":true}],"source":"Schéma dessiné pour l’exercice"}],"questions":[{"enonce":"Touche **le carré qui semble avancer** vers le spectateur.","aide":"Les couleurs chaudes semblent avancer, les froides semblent reculer.","type":"zone","document":"cadres","multiple":false},{"enonce":"Range ces couleurs dans la bonne famille.","aide":"Les chaudes rappellent le feu et le soleil ; les froides rappellent l’eau et la forêt.","type":"categories","categories":[{"id":"c0","texte":"Chaudes"},{"id":"c1","texte":"Froides"}],"items":[{"id":"i0","texte":"Rouge"},{"id":"i1","texte":"Orange"},{"id":"i2","texte":"Bleu"},{"id":"i3","texte":"Jaune"},{"id":"i4","texte":"Vert"}]},{"enonce":"Sacha peint maintenant des montagnes très lointaines. Quelles couleurs va-t-il choisir pour qu’elles paraissent loin ?","aide":"Pour reculer, une couleur doit appartenir à la famille qui « s’éloigne » du regard.","type":"choix","options":[{"id":"a","texte":"Des jaunes très vifs, couleurs lumineuses"},{"id":"b","texte":"Des bleus et des verts, couleurs froides"},{"id":"c","texte":"Des rouges et des oranges, couleurs chaudes"},{"id":"d","texte":"Des couleurs chaudes, mais très sombres"}],"multiple":false},{"enonce":"Complète la règle que Sacha retient.","aide":"Les couleurs qui avancent vont devant, celles qui reculent vont derrière.","type":"trous","segments":["Pour créer de la ",0," sans ligne de perspective, on place des couleurs ",1," au premier plan et des couleurs ",2," au fond."],"banque":["sombres","froides","chaudes","profondeur","saturées"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Dans l’essai 1, le carré orangé, de teinte **chaude**, se détache et semble avancer ; dans l’essai 2, le carré bleu, de teinte **froide**, semble reculer dans le fond."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Les **rouges, oranges et jaunes** sont chauds et avancent ; les **bleus et verts** sont froids et reculent."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les couleurs **froides** reculent : bleus et verts donnent l’impression que les montagnes sont loin, sans tracer une seule ligne de perspective."},{"cle":{"type":"trous","trous":[["profondeur"],["chaudes"],["froides"]]},"affichage":"profondeur · chaudes · froides","explication":"Les couleurs **chaudes** avancent (premier plan), les **froides** reculent (fond) : cela crée de la **profondeur**."}]$ex$::jsonb),
  ('5a4bc8ef-ec15-5356-af90-cb8ef5afcf17'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les échantillons de Mme Roux","competence":"lire-tableau","situation":"Mme Roux a classé cinq échantillons de peinture en notant, pour chacun, sa valeur et sa saturation. Elle demande à Mathis de s’en servir pour préparer un coucher de soleil.","documents":[{"id":"echantillons","type":"tableau","titre":"Fiche des échantillons","colonnes":["Échantillon","Valeur (1 très sombre, 5 très clair)","Saturation (1 terne, 5 vive)"],"lignes":[["Bleu de nuit",1,5],["Rose dragée",4,2],["Gris-bleu",2,1],["Jaune citron",5,4],["Vert mousse",3,3]],"source":"Notes imaginées pour l’exercice"},{"id":"consigne","type":"texte","genre":"consigne","titre":"La consigne de Mme Roux","blocs":["Peins un coucher de soleil : le ciel est orange.","Place à côté de l’orange une couleur qui le fasse vibrer.","Tu dois garder des couleurs éclatantes : ne les mélange pas dans le même pot."]}],"questions":[{"enonce":"Touche **la saturation la plus faible** de la fiche (l’échantillon le plus terne).","aide":"Cherche le plus petit nombre dans la colonne de la saturation.","type":"zone","document":"echantillons","multiple":false},{"enonce":"Range les échantillons **du plus sombre au plus clair**.","aide":"Pour cela, regarde seulement la colonne « Valeur » : 1 est le plus sombre.","type":"ordre","items":[{"id":"a","texte":"Gris-bleu"},{"id":"b","texte":"Vert mousse"},{"id":"c","texte":"Rose dragée"},{"id":"d","texte":"Jaune citron"},{"id":"e","texte":"Bleu de nuit"}]},{"enonce":"Mathis affirme : « Une couleur vive est forcément claire. » Quel échantillon prouve qu’il a tort ?","aide":"Cherche une couleur très saturée dont la valeur est pourtant très basse.","type":"choix","options":[{"id":"a","texte":"Jaune citron"},{"id":"b","texte":"Gris-bleu"},{"id":"c","texte":"Bleu de nuit"},{"id":"d","texte":"Rose dragée"}],"multiple":false},{"enonce":"D’après la consigne, quelle couleur Mathis posera-t-il à côté du ciel orange pour le faire vibrer ?","aide":"Sur le cercle chromatique, la complémentaire de l’orange est en face de lui.","type":"choix","options":[{"id":"a","texte":"Du jaune, qui est sa voisine"},{"id":"b","texte":"Du bleu, qui est sa complémentaire"},{"id":"c","texte":"Du rouge, qui est sa voisine"},{"id":"d","texte":"Du vert, qui est sa voisine"}],"multiple":false},{"enonce":"Complète ce que Mathis doit se rappeler.","aide":"Le même couple peut donner l’effet le plus vif ou le plus terne.","type":"trous","segments":["Côte à côte, deux complémentaires se ",0," ; mélangées dans le même pot, elles s’",1," en gris."],"banque":["séparent","colorent","renforcent","éteignent"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"La saturation la plus faible est **1** : c’est le gris-bleu, le plus terne des cinq."},{"cle":{"type":"ordre","ids":["e","a","b","c","d"]},"explication":"On suit la valeur : **1** Bleu de nuit, **2** Gris-bleu, **3** Vert mousse, **4** Rose dragée, **5** Jaune citron."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **bleu de nuit** est vif (saturation 5) et très sombre (valeur 1) : valeur et saturation sont **indépendantes**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le **bleu** est complémentaire de l’orange : posés côte à côte, les deux se renforcent et vibrent."},{"cle":{"type":"trous","trous":[["renforcent"],["eteignent"]]},"affichage":"renforcent · éteignent","explication":"Côte à côte, les complémentaires se **renforcent** ; mélangées, elles s’**éteignent** en gris. D’où la consigne : ne pas les mélanger."}]$ex$::jsonb),
  ('d385ebb2-0f30-5639-af46-c6cc002f48b3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les maisons du lotissement","competence":"observer-schema","situation":"Camille dessine trois maisons dans un lotissement. Sans tracer aucune ligne, elle veut qu’on voie laquelle est la plus proche et laquelle est la plus lointaine.","documents":[{"id":"maisons","type":"schema","titre":"Le dessin de Camille","largeur":320,"hauteur":230,"elements":[{"forme":"rect","x":130,"y":95,"l":80,"h":70,"teinte":"sable","motif":"plein","id":"z1","zone":true,"texte":"B"},{"forme":"rect","x":235,"y":50,"l":40,"h":35,"teinte":"gris","motif":"plein","id":"z2","zone":true,"texte":"C"},{"forme":"rect","x":40,"y":120,"l":110,"h":90,"teinte":"brun","motif":"plein","id":"z3","zone":true,"texte":"A"}],"source":"Dessin imaginé pour l’exercice"}],"questions":[{"enonce":"Touche **la maison la plus proche** du spectateur.","aide":"La maison la plus proche est celle qui en cache une autre.","type":"zone","document":"maisons","multiple":false},{"enonce":"Range les maisons **de la plus proche à la plus lointaine**.","aide":"Utilise ensemble la taille et la hauteur sur la feuille.","type":"ordre","items":[{"id":"a","texte":"Maison B"},{"id":"b","texte":"Maison C"},{"id":"c","texte":"Maison A"}]},{"enonce":"Associe chaque procédé à sa règle.","aide":"Pense à ce que tu viens d’observer sur le dessin de Camille.","type":"association","gauche":[{"id":"g0","texte":"Superposition"},{"id":"g1","texte":"Étagement"},{"id":"g2","texte":"Taille relative"}],"droite":[{"id":"d0","texte":"Ce qui est plus haut sur la feuille est plus loin"},{"id":"d1","texte":"Ce qui cache est devant"},{"id":"d2","texte":"Plus c’est petit, plus c’est loin"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La maison **A** est devant : elle cache une partie de B (**superposition**), elle est dessinée la plus grande et la plus basse."},{"cle":{"type":"ordre","ids":["c","a","b"]},"explication":"A cache B, donc A est devant. C est plus petite et plus haute sur la feuille que B : elle est la plus **lointaine**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Trois procédés simples : la **superposition** (qui cache est devant), l’**étagement** (plus haut = plus loin) et la **taille relative** (plus petit = plus loin)."}]$ex$::jsonb),
  ('d385ebb2-0f30-5639-af46-c6cc002f48b3'::uuid, 2, 2, 10, 35, 4,
