  ('d385ebb2-0f30-5639-af46-c6cc002f48b3'::uuid, 3, 3, 15, 50, 3,
   $ex${"titre":"Le paysage de montagne de Hugo","competence":"analyser-document","situation":"Hugo a dessiné un paysage avec des montagnes, des collines, une maison et deux arbres. Son professeur lui demande de retrouver tous les procédés qui donnent de la profondeur.","documents":[{"id":"paysage","type":"schema","titre":"Le paysage de Hugo","largeur":320,"hauteur":230,"elements":[{"forme":"polygone","points":[[20,110],[90,45],[150,95],[210,40],[300,110]],"teinte":"ciel","motif":"clair","id":"z1","zone":true},{"forme":"ellipse","cx":160,"cy":140,"rx":140,"ry":40,"teinte":"vert","motif":"clair","id":"z2","zone":true},{"forme":"rect","x":205,"y":115,"l":45,"h":35,"teinte":"brun","motif":"plein","id":"z3","zone":true},{"forme":"cercle","cx":215,"cy":135,"r":26,"teinte":"vert","motif":"plein","id":"z4","zone":true},{"forme":"cercle","cx":80,"cy":125,"r":8,"teinte":"vert","motif":"plein","id":"z5","zone":true},{"forme":"polygone","points":[[105,218],[215,218],[175,160],[145,160]],"teinte":"sable","motif":"plein","id":"z6","zone":true}],"source":"Dessin imaginé pour l’exercice"},{"id":"indices","type":"tableau","titre":"Les remarques de Hugo","colonnes":["Ce que Hugo a remarqué"],"lignes":[["Les montagnes sont pâles et bleutées"],["Un arbre cache une partie de la maison"],["Le sentier est en bas de la feuille, les collines plus haut"],["Le petit arbre est minuscule à côté du grand"]]}],"questions":[{"enonce":"Touche **l’élément qui est caché en partie** par un arbre.","aide":"Regarde ce qui est recouvert par le grand arbre.","type":"zone","document":"paysage","multiple":false},{"enonce":"Associe chaque remarque de Hugo au procédé qu’elle illustre.","aide":"Les trois procédés simples sont la superposition, l’étagement et la taille relative.","type":"association","gauche":[{"id":"g0","texte":"Montagnes pâles et bleutées"},{"id":"g1","texte":"Un arbre cache la maison"},{"id":"g2","texte":"Sentier en bas, collines plus haut"},{"id":"g3","texte":"Un petit arbre à côté d’un grand"}],"droite":[{"id":"d0","texte":"Étagement"},{"id":"d1","texte":"Superposition"},{"id":"d2","texte":"Taille relative"},{"id":"d3","texte":"Perspective atmosphérique"}]},{"enonce":"Hugo a utilisé un procédé que cet artiste de la Renaissance emploie dans les arrière-plans de ses tableaux. Lequel ?","aide":"Pense au procédé qui rend les objets lointains pâles, bleutés et flous.","type":"choix","options":[{"id":"a","texte":"Marcel Duchamp"},{"id":"b","texte":"Léonard de Vinci"},{"id":"c","texte":"Max Ernst"},{"id":"d","texte":"Jackson Pollock"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"La **maison** est en partie cachée par le grand arbre : ce qui cache est devant, donc l’arbre est plus proche."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Pâleur et teinte bleutée : **perspective atmosphérique**. Un arbre devant la maison : **superposition**. Plus haut = plus loin : **étagement**. Plus petit = plus loin : **taille relative**."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Léonard de Vinci** emploie la perspective atmosphérique dans les arrière-plans de ses tableaux."}]$ex$::jsonb),
  ('2093a9de-c71f-58d1-b146-507bede95b8e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le placard de l’atelier de Maëlle","competence":"lire-tableau","situation":"Maëlle range le placard de l’atelier d’arts plastiques. Sur l’inventaire, elle doit retrouver chaque matériau et le mettre dans la bonne famille.","documents":[{"id":"inventaire","type":"tableau","titre":"Inventaire du placard","colonnes":["Matériau","Quantité"],"lignes":[["Crayons",12],["Fusains",5],["Encre (flacons)",3],["Gouache (tubes)",8],["Aquarelle (godets)",6],["Pastels",10],["Chutes de tissu",7],["Journaux",9]],"source":"Inventaire imaginé pour l’exercice"}],"questions":[{"enonce":"Touche le nom du matériau qui est **un bâtonnet de charbon de bois** pour dessiner.","aide":"Il laisse un trait noir et très friable.","type":"zone","document":"inventaire","multiple":false},{"enonce":"Range chaque matériau dans sa famille.","aide":"Les matières rapportées sont celles qu’on ajoute à l’œuvre, déjà fabriquées.","type":"categories","categories":[{"id":"c0","texte":"Traçants"},{"id":"c1","texte":"Peintures"},{"id":"c2","texte":"Matières rapportées"}],"items":[{"id":"i0","texte":"Gouache"},{"id":"i1","texte":"Crayon"},{"id":"i2","texte":"Pastel"},{"id":"i3","texte":"Fusain"},{"id":"i4","texte":"Encre"},{"id":"i5","texte":"Journal"},{"id":"i6","texte":"Aquarelle"},{"id":"i7","texte":"Tissu"}]},{"enonce":"Combien d’objets **traçants** (crayons, fusains, encre) compte l’inventaire en tout ?","aide":"Additionne seulement les trois lignes de la famille des traçants.","type":"nombre"}]}$ex$::jsonb,
