  ('2093a9de-c71f-58d1-b146-507bede95b8e'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Trois outils, trois traces","competence":"analyser-document","situation":"Un élève veut recouvrir un grand fond de la même couleur. Selon l’outil choisi, la trace sera très différente : sa professeure lui remet deux fiches, l’une sur les outils, l’autre sur les gestes.","documents":[{"id":"outils","type":"tableau","titre":"Trois outils pour une même couleur","colonnes":["Outil","Trace laissée"],"lignes":[["Pinceau","Trait précis, qui suit le geste"],["Rouleau","Aplat large et régulier, sans détail"],["Éponge","Surface piquetée, aux bords flous"]],"source":"Fiche écrite pour l’exercice"},{"id":"gestes","type":"tableau","titre":"Cinq gestes, cinq traces","colonnes":["Geste","Ce que l’on voit"],"lignes":[["Tracer","Une ligne continue"],["Frotter","La texture du support révélée sur le papier"],["Gratter","La couche du dessus enlevée, celle du dessous visible"],["Déchirer","Un bord irrégulier et effiloché"],["Tamponner","Des petites taches répétées"]]}],"questions":[{"enonce":"L’élève veut un fond large et régulier, sans détail, en quelques secondes. Quel outil choisit-il ?","aide":"Cherche, dans la fiche des outils, la trace « large et régulière ».","type":"choix","options":[{"id":"a","texte":"Le crayon"},{"id":"b","texte":"L’éponge"},{"id":"c","texte":"Le pinceau fin"},{"id":"d","texte":"Le rouleau"}],"multiple":false},{"enonce":"Associe chaque trace au geste qui la produit.","aide":"Relis la fiche des gestes : chaque geste y a sa trace.","type":"association","gauche":[{"id":"g0","texte":"Un bord irrégulier et effiloché"},{"id":"g1","texte":"La texture du bois visible sur la feuille"},{"id":"g2","texte":"Des petites taches répétées"},{"id":"g3","texte":"La couche du dessous qui réapparaît"}],"droite":[{"id":"d0","texte":"Frotter"},{"id":"d1","texte":"Tamponner"},{"id":"d2","texte":"Gratter"},{"id":"d3","texte":"Déchirer"}]},{"enonce":"Complète la phrase de la professeure.","aide":"Le premier mot est la peinture, le second est ce que le spectateur voit.","type":"trous","segments":["Une même ",0," n’a pas le même ",1," posée au pinceau, au rouleau ou à l’éponge."],"banque":["support","format","effet","couleur"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Le **rouleau** laisse un aplat large et régulier. Le pinceau suit le geste, l’éponge pique la surface."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Chaque geste laisse une trace **reconnaissable** : déchirer, frotter, tamponner, gratter ne produisent jamais le même effet."},{"cle":{"type":"trous","trous":[["couleur"],["effet"]]},"affichage":"couleur · effet","explication":"Une même **couleur** n’a pas le même **effet** selon l’outil : le geste et l’outil font partie de l’œuvre."}]$ex$::jsonb),
  ('2093a9de-c71f-58d1-b146-507bede95b8e'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Deux artistes et le hasard","competence":"analyser-texte","situation":"Au musée, deux cartels expliquent comment deux artistes ont fait entrer le hasard dans leurs œuvres. Marion les lit pour répondre à une question de son carnet : le hasard, est-ce de la négligence ?","documents":[{"id":"ernst","type":"texte","genre":"source","titre":"Cartel 1","auteur":"Cartel rédigé pour l’exercice","blocs":["Max Ernst (1891-1976) pose une feuille sur du bois, du tissu ou des feuilles, puis la frotte au crayon : c’est le frottage.","La texture apparaît d’elle-même. L’artiste garde les formes qui lui évoquent des paysages."]},{"id":"pollock","type":"texte","genre":"source","titre":"Cartel 2","auteur":"Cartel rédigé pour l’exercice","blocs":["Jackson Pollock (1912-1956) pose sa toile au sol. Il laisse couler et goutter la peinture en se déplaçant tout autour.","Il choisit ses couleurs, son geste, la hauteur de la coulure, et s’arrête quand l’équilibre lui convient."]}],"questions":[{"enonce":"Touche **le mot qui nomme la technique** de Max Ernst dans le premier cartel.","aide":"C’est le nom donné au fait de frotter un crayon sur une feuille posée sur une surface texturée.","type":"zone","document":"ernst","multiple":false},{"enonce":"Range ces descriptions selon l’artiste auquel elles se rapportent.","aide":"Le frottage demande un support texturé et un crayon ; le dripping, de la peinture liquide.","type":"categories","categories":[{"id":"c0","texte":"Max Ernst"},{"id":"c1","texte":"Jackson Pollock"}],"items":[{"id":"i0","texte":"La texture d’un tissu qui apparaît"},{"id":"i1","texte":"Une feuille posée sur du bois"},{"id":"i2","texte":"Une toile posée au sol"},{"id":"i3","texte":"Un crayon frotté sur le papier"},{"id":"i4","texte":"La peinture qui coule et goutte"},{"id":"i5","texte":"L’artiste tourne autour de l’œuvre"}]},{"enonce":"Réponds à la question du carnet de Marion.","aide":"Pollock « choisit » et « s’arrête quand l’équilibre lui convient » : il décide.","type":"trous","segments":["Provoquer un ",0," et savoir le garder est un ",1," ; le hasard en art est une ",2,", pas de la négligence."],"banque":["savoir-faire","erreur","décision","négligence","accident"]},{"enonce":"Quel artiste fait **couler** la peinture sur une toile posée au sol ?","aide":"Relis le cartel où l’artiste « se déplace tout autour » de sa toile.","type":"choix","options":[{"id":"a","texte":"Jackson Pollock"},{"id":"b","texte":"Max Ernst"},{"id":"c","texte":"Aucun des deux"},{"id":"d","texte":"Les deux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m22"]},"explication":"La technique de Max Ernst est le **frottage** : la texture du support apparaît sur la feuille."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c1"}},"explication":"Ernst pratique le **frottage** (feuille, crayon, texture) ; Pollock pratique le **dripping** (toile au sol, peinture qui coule)."},{"cle":{"type":"trous","trous":[["accident"],["savoir faire"],["decision"]]},"affichage":"accident · savoir-faire · décision","explication":"Provoquer un **accident** et savoir le garder est un **savoir-faire** : le hasard maîtrisé est une **décision**."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Jackson Pollock** : c’est le dripping. Max Ernst, lui, frotte un crayon sur une feuille."}]$ex$::jsonb),
  ('0165dc05-4a53-5233-b1a2-4a0dbe4ac780'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le groupe de la 6e B","competence":"analyser-document","situation":"Dans le groupe de messages de la 6e B, plusieurs élèves se moquent de Lola, qui n’y est pas. Tu lis leur conversation pour savoir si c’est du harcèlement.","documents":[{"id":"groupe","type":"dialogue","modele":"sms","titre":"Le groupe de la 6e B","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"gauche"},{"nom":"Sacha","emoji":"🧒","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"Regardez la photo de Lola à la cantine 😂"},{"qui":"Tom","texte":"Encore son sac tout abîmé ! Je l’appelle Limace maintenant."},{"qui":"Sacha","texte":"Lundi on l’a mise à l’écart au foot. Mardi aussi. Et on lui a pris son cartable."},{"qui":"Nina","texte":"On recommence demain : personne ne lui parle."},{"qui":"Tom","texte":"Au fait, qui a fini l’exercice de maths ?"}],"source":"Conversation écrite pour l’exercice"}],"questions":[{"enonce":"Touche le surnom que le groupe donne à Lola.","aide":"Cherche le mot que Tom emploie pour « appeler » Lola.","type":"zone","document":"groupe","multiple":false},{"enonce":"Complète la règle du cours.","aide":"Dans la conversation, ça recommence lundi, mardi, demain… et ils sont plusieurs.","type":"trous","segments":["Une moquerie ",0," contre la même personne, par un ",1,", c’est du harcèlement."],"banque":["répétée","ami","groupe","unique"]},{"enonce":"Relie chaque geste à sa forme de harcèlement.","aide":"Verbale = les mots ; sociale = l’écart ; matérielle = les affaires ; cyber = l’écran ; physique = le corps.","type":"association","gauche":[{"id":"g0","texte":"Le surnom « Limace »"},{"id":"g1","texte":"Personne ne lui parle"},{"id":"g2","texte":"On lui prend son cartable"},{"id":"g3","texte":"La photo moquée envoyée au groupe"},{"id":"g4","texte":"Des coups dans le couloir"}],"droite":[{"id":"d0","texte":"Sociale"},{"id":"d1","texte":"Cyber"},{"id":"d2","texte":"Verbale"},{"id":"d3","texte":"Physique"},{"id":"d4","texte":"Matérielle"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"Le surnom est **Limace**. Un surnom moqueur répété est une forme de harcèlement verbal."},{"cle":{"type":"trous","trous":[["repetee"],["groupe"]]},"affichage":"répétée · groupe","explication":"Le harcèlement est une violence **répétée**, souvent menée par un **groupe** contre quelqu’un qui ne peut pas se défendre."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g4":"d3","g2":"d4"}},"explication":"Insultes et surnoms : **verbale**. Mise à l’écart : **sociale**. Vol d’affaires : **matérielle**. Photo ou message en ligne : **cyber**. Coups : **physique**."}]$ex$::jsonb),
  ('0165dc05-4a53-5233-b1a2-4a0dbe4ac780'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le bus de 17 h 10","competence":"analyser-texte","situation":"Yanis prend le bus après les cours. Depuis lundi, il voit une scène qui le met mal à l’aise. Que peut-il faire, lui qui est témoin ?","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Le témoignage de Yanis","auteur":"Texte écrit pour l’exercice","blocs":["Je m’appelle Yanis et je prends le bus de 17 h 10. Depuis lundi, trois élèves de 3e s’en prennent à Sam, un élève de 6e.","Lundi, ils lui ont pris sa casquette. Mardi, ils ont dit qu’il sentait mauvais. Jeudi, ils ont recommencé devant tout le bus.","Quelques élèves rient. D’autres regardent leur téléphone. Moi, je n’ai rien dit."]},{"id":"echange","type":"dialogue","modele":"bulles","titre":"Yanis et Camille à la sortie","participants":[{"nom":"Camille","emoji":"👧","cote":"gauche"},{"nom":"Yanis","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Camille","texte":"Si tu préviens la CPE, tu vas rapporter. C’est nul !"},{"qui":"Yanis","texte":"Non. Rapporter, c’est vouloir nuire à quelqu’un. Moi, je veux que Sam soit protégé."},{"qui":"Camille","texte":"Ah… alors toi, tu signales."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"D’après le témoignage, pendant combien de jours différents Sam a-t-il été embêté cette semaine ?","aide":"Relève les trois jours cités dans le deuxième paragraphe.","type":"nombre","unite":"jours"},{"enonce":"Touche le mot qui montre des élèves qui encouragent les moqueries.","aide":"Un groupe qui encourage montre qu’il trouve ça drôle.","type":"zone","document":"recit","multiple":false},{"enonce":"Range chaque attitude de témoin : elle encourage, ou elle protège ?","aide":"Pour le cours, ne rien faire, c’est déjà choisir un camp.","type":"categories","categories":[{"id":"c0","texte":"Ça encourage"},{"id":"c1","texte":"Ça protège"}],"items":[{"id":"i0","texte":"Regarder ailleurs sans rien dire"},{"id":"i1","texte":"Aller parler à Sam après"},{"id":"i2","texte":"Filmer la scène pour la montrer"},{"id":"i3","texte":"Dire « arrêtez » avec d’autres élèves"},{"id":"i4","texte":"Prévenir un adulte"},{"id":"i5","texte":"Rire avec les autres"}]},{"enonce":"Touche le mot qui montre que Yanis veut signaler, pas rapporter.","aide":"Signaler, c’est protéger quelqu’un.","type":"zone","document":"echange","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 jours","explication":"Lundi, mardi et jeudi : **3 jours**. C’est la **répétition**, un des trois éléments du harcèlement."},{"cle":{"type":"zone","ids":["m53"]},"explication":"Les élèves qui **rient** encouragent les harceleurs : un groupe qui rit donne raison à celui qui se moque."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c1","i5":"c0"}},"explication":"Rire, filmer et se taire **encouragent** ; prévenir un adulte, soutenir Sam et dire stop **protègent**."},{"cle":{"type":"zone","ids":["m25"]},"explication":"Yanis veut que Sam soit **protégé** : **signaler protège**, alors que rapporter vise à nuire."}]$ex$::jsonb),
  ('0165dc05-4a53-5233-b1a2-4a0dbe4ac780'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Des messages à 23 h","competence":"analyser-document","situation":"Lola reçoit des messages d’un compte sans nom, le soir, dans sa chambre. Elle ne sait pas quoi faire. Tu l’aides à comprendre et à réagir.","documents":[{"id":"nuit","type":"dialogue","modele":"sms","titre":"Le téléphone de Lola, 23 h 12","participants":[{"nom":"Compte anonyme","emoji":"👤","cote":"gauche"},{"nom":"Lola","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Compte anonyme","texte":"Tu dors déjà ? Tout le monde a ta photo. 😂"},{"qui":"Compte anonyme","texte":"Elle a déjà été partagée vingt fois."},{"qui":"Lola","texte":"Laisse-moi tranquille…"},{"qui":"Compte anonyme","texte":"Personne ne saura jamais que c’est moi. 😈"},{"qui":"Compte anonyme","texte":"Demain, on recommence."}],"source":"Conversation écrite pour l’exercice"},{"id":"numeros","type":"fiche","modele":"panneau","titre":"Les numéros à connaître","entete":"Besoin d’aide ?","emoji":"📞","lignes":[{"texte":"3018","valeur":"Harcèlement et cyberharcèlement","id":"z1"},{"texte":"119","valeur":"Enfance en danger","id":"z2"},{"texte":"15","valeur":"Urgence médicale (SAMU)","id":"z3"},{"texte":"17","valeur":"Police, gendarmerie","id":"z4"}],"pied":"Le 3018 est gratuit et anonyme."}],"questions":[{"enonce":"Combien de messages le compte anonyme envoie-t-il à Lola ?","aide":"Ne compte pas la réponse de Lola.","type":"nombre","unite":"messages"},{"enonce":"Pourquoi le cyberharcèlement est-il pire ? Relie chaque cause à sa conséquence.","aide":"Pense au message reçu à 23 h et à la photo partagée vingt fois.","type":"association","gauche":[{"id":"g0","texte":"Il ne s’arrête pas à la grille"},{"id":"g1","texte":"Les traces restent"},{"id":"g2","texte":"Le harceleur se croit protégé"}],"droite":[{"id":"d0","texte":"Elles se rediffusent"},{"id":"d1","texte":"Il suit la victime chez elle, la nuit"},{"id":"d2","texte":"Une adresse IP s’identifie"}]},{"enonce":"Le compte écrit : « Personne ne saura jamais que c’est moi. » Est-ce vrai ?","aide":"Relis ce que dit le cours sur l’écran qui « protège ».","type":"choix","options":[{"id":"a","texte":"Oui : un compte sans nom est introuvable"},{"id":"b","texte":"Oui : seul le prénom permet de le retrouver"},{"id":"c","texte":"Oui : il suffit qu’il efface son compte"},{"id":"d","texte":"Non : une adresse IP permet de l’identifier"}],"multiple":false},{"enonce":"Remets dans l’ordre les gestes que Lola peut faire.","aide":"On commence par chercher de l’aide, et on finit par couper le contact.","type":"ordre","items":[{"id":"a","texte":"Conserver les preuves par captures d’écran"},{"id":"b","texte":"Bloquer le compte"},{"id":"c","texte":"Ne pas répondre aux provocations"},{"id":"d","texte":"En parler à un adulte"}]},{"enonce":"Touche le numéro que Lola peut appeler, gratuit et anonyme, contre le cyberharcèlement.","aide":"Cherche la ligne qui parle de harcèlement et de cyberharcèlement.","type":"zone","document":"numeros","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 messages","explication":"Le compte anonyme écrit **4 messages** : le harcèlement est **répété**, même la nuit."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"À l’écran, le harcèlement **suit Lola chez elle**, les traces **se rediffusent**, et le harceleur n’est pas aussi caché qu’il le croit : une **adresse IP s’identifie**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le harceleur se croit caché, mais une **adresse IP s’identifie** : il peut être retrouvé."},{"cle":{"type":"ordre","ids":["d","a","c","b"]},"explication":"En parler à un adulte → **garder les preuves** → **ne pas répondre** → **bloquer**."},{"cle":{"type":"zone","ids":["z1"]},"explication":"Le **3018** répond au harcèlement et au cyberharcèlement, gratuitement et sans donner son nom."}]$ex$::jsonb),
