   $ex${"titre":"La robotique, c’est pour les garçons ?","competence":"argumenter","situation":"Anaïs voudrait s’inscrire au club de robotique du collège. Hugo lui dit que ce n’est pas pour elle. Tu analyses ce qu’il dit.","documents":[{"id":"club","type":"dialogue","modele":"bulles","titre":"Dans la cour","participants":[{"nom":"Hugo","emoji":"👦","cote":"gauche"},{"nom":"Anaïs","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Anaïs","texte":"Je voudrais m’inscrire au club de robotique."},{"qui":"Hugo","texte":"La robotique, c’est toujours pour les garçons."},{"qui":"Anaïs","texte":"Qui a dit ça ? Au collège, on a les mêmes cours et la même liberté de choisir."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Hugo transforme une idée en règle pour tous. Touche le mot qui le montre.","aide":"Cherche le mot qui ne laisse aucune exception.","type":"zone","document":"club","multiple":false},{"enonce":"Range chaque phrase : stéréotype, ou fait que l’on peut vérifier ?","aide":"Un fait se compte ou se vérifie ; un stéréotype range toutes les filles ou tous les garçons dans une case.","type":"categories","categories":[{"id":"c0","texte":"Stéréotype"},{"id":"c1","texte":"Fait vérifiable"}],"items":[{"id":"i0","texte":"Les garçons sont nuls en lecture"},{"id":"i1","texte":"Le club de robotique a lieu le mardi"},{"id":"i2","texte":"Il y a 14 filles dans la classe de 6e A"},{"id":"i3","texte":"Les garçons ne pleurent jamais"},{"id":"i4","texte":"Les filles ne savent pas jouer au foot"},{"id":"i5","texte":"Léa a eu 18 sur 20 au contrôle de maths"}]},{"enonce":"D’après la règle, Anaïs peut-elle s’inscrire au club de robotique ?","aide":"Relis la réponse d’Anaïs : elle dit ce que garantit la loi.","type":"choix","options":[{"id":"a","texte":"Non : la loi réserve ce club aux garçons, comme chaque année"},{"id":"b","texte":"Non : seulement si un garçon l’accompagne tout le temps"},{"id":"c","texte":"Non : seulement si elle a de meilleures notes que les garçons"},{"id":"d","texte":"Oui : filles et garçons ont les mêmes droits et la même liberté"}],"multiple":false}]}$ex$::jsonb,
