  ('74137f62-de99-5c1d-a450-5a479535c67b'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le cousin se trompe sur les symboles","competence":"analyser-texte","situation":"À la sortie du défilé, le cousin de Maëlys explique les symboles à tout le monde. Il se trompe plusieurs fois. Tu corriges.","documents":[{"id":"cousin","type":"texte","genre":"recit","titre":"Ce que dit le cousin","auteur":"Texte écrit pour l’exercice","blocs":["« Le coq gaulois est un symbole officiel de la République. Marianne, c’était une vraie femme qui a existé. »","« La Marseillaise s’appelle ainsi parce qu’elle a été écrite à Marseille, en 1792. Et le drapeau tricolore est né en 1790. »","« Le 14 Juillet, on fête seulement la prise de la Bastille. Et le bonnet de Marianne, c’était celui des esclaves affranchis de Rome. »"]}],"questions":[{"enonce":"Touche la ville que le cousin cite à tort comme lieu d’écriture de la Marseillaise.","aide":"Le chant doit son nom aux fédérés marseillais, qui le chantaient en montant à Paris.","type":"zone","document":"cousin","multiple":false},{"enonce":"Dans quelle ville Rouget de Lisle a-t-il écrit ce chant en 1792 ?","aide":"C’est une ville de l’est de la France, au bord du Rhin.","type":"texte","placeholder":"Une ville"},{"enonce":"Le cousin dit six choses. Range-les : vrai ou faux ?","aide":"Le coq est un symbole ancien et non officiel ; Marianne est une figure, pas une personne.","type":"categories","categories":[{"id":"c0","texte":"Vrai"},{"id":"c1","texte":"Faux"}],"items":[{"id":"i0","texte":"Le 14 Juillet fête un seul événement"},{"id":"i1","texte":"Le coq gaulois est un symbole officiel"},{"id":"i2","texte":"Marianne a réellement existé"},{"id":"i3","texte":"La Marseillaise a été écrite à Marseille"},{"id":"i4","texte":"Les esclaves affranchis de Rome portaient le bonnet phrygien"},{"id":"i5","texte":"Le drapeau tricolore est né en 1790"}]},{"enonce":"À quoi servent ces symboles, visibles partout ?","aide":"Un symbole est un raccourci qui rappelle une histoire commune.","type":"choix","options":[{"id":"a","texte":"À remplacer les lois votées par le Parlement"},{"id":"b","texte":"À montrer qui sont les meilleurs élèves"},{"id":"c","texte":"À décorer les bâtiments publics"},{"id":"d","texte":"À rappeler que les citoyens forment une même communauté"}],"multiple":false}]}$ex$::jsonb,
