   $ex${"titre":"Une journée de Zoé au collège","competence":"lire-tableau","situation":"Zoé raconte sa journée de collégienne. Tu retrouves ce qui relève de la liberté, de l’égalité ou de la fraternité.","documents":[{"id":"journee","type":"tableau","titre":"La journée de Zoé","colonnes":["Heure","Ce qui se passe"],"lignes":[["8 h","Karim donne son avis sur le menu de la cantine devant la classe."],["10 h","Tous les élèves de la classe ont les mêmes cours dans la même école gratuite."],["12 h","Lina voit Sofia seule au réfectoire et vient manger avec elle."]],"enteteLignes":true,"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche la scène qui montre la fraternité.","aide":"La fraternité, c’est se sentir concerné par les autres.","type":"zone","document":"journee","multiple":false},{"enonce":"Complète la phrase du cours.","aide":"Ma liberté s’arrête quand elle gêne quelqu’un d’autre.","type":"trous","segments":["La liberté de chacun s’arrête là où commence celle des ",0,"."],"banque":["adultes","autres","cours","lois"]},{"enonce":"Relie chaque situation à la valeur de la devise.","aide":"Liberté = penser et s’exprimer ; égalité = mêmes droits ; fraternité = entraide.","type":"association","gauche":[{"id":"g0","texte":"Choisir de s’exprimer dans le journal du collège"},{"id":"g1","texte":"Avoir les mêmes droits quelle que soit sa religion"},{"id":"g2","texte":"Aider un camarade qui n’a pas compris la leçon"}],"droite":[{"id":"d0","texte":"Liberté"},{"id":"d1","texte":"Fraternité"},{"id":"d2","texte":"Égalité"}]}]}$ex$::jsonb,
