   $ex${"titre":"Du temps en plus pour Samir","competence":"argumenter","situation":"Pendant un contrôle de 45 minutes, Samir, dyslexique, a le droit à 15 minutes de plus. Théo trouve ça injuste. Tu expliques.","documents":[{"id":"couloir","type":"dialogue","modele":"bulles","titre":"À la fin du contrôle","participants":[{"nom":"Théo","emoji":"👦","cote":"gauche"},{"nom":"Mme Roux","emoji":"👩‍🏫","cote":"droite"}],"repliques":[{"qui":"Théo","texte":"Samir a eu 15 minutes de plus. C’est un privilège !"},{"qui":"Mme Roux","texte":"Non. Ce temps en plus l’aide à lutter à armes égales avec vous."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot que Théo emploie à tort pour parler du temps en plus.","aide":"Cherche le mot qui voudrait dire « avantage injuste ».","type":"zone","document":"couloir","multiple":false},{"enonce":"Combien de minutes Samir a-t-il en tout pour le contrôle ?","aide":"Ajoute le temps du contrôle (45 min) et le temps en plus.","type":"nombre","unite":"minutes"},{"enonce":"Que représente ce temps en plus ?","aide":"Traiter également des personnes en situation inégale ne suffit pas.","type":"choix","options":[{"id":"a","texte":"Un cadeau du professeur"},{"id":"b","texte":"Une mesure d’équité"},{"id":"c","texte":"Une sanction envers les autres élèves"},{"id":"d","texte":"Une récompense pour bon comportement"}],"multiple":false},{"enonce":"Range chaque exemple : même traitement pour tous (égalité), ou aide adaptée (équité) ?","aide":"Se demander : tout le monde reçoit-il exactement la même chose, ou bien l’aide dépend-elle de la situation ?","type":"categories","categories":[{"id":"c0","texte":"Même traitement pour tous"},{"id":"c1","texte":"Aide adaptée"}],"items":[{"id":"i0","texte":"Les mêmes cours pour tous les élèves de 6e"},{"id":"i1","texte":"Une rampe pour un élève en fauteuil roulant"},{"id":"i2","texte":"Une aide pour payer la cantine à une famille en difficulté"},{"id":"i3","texte":"Le même règlement intérieur pour tous"},{"id":"i4","texte":"Du temps en plus pour un élève dyslexique"},{"id":"i5","texte":"L’école gratuite pour tous"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m10"]},"explication":"Théo parle de **privilège** : ce temps en plus n’en est pas un, il rétablit l’égalité réelle."},{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 minutes","explication":"45 + 15 = **60 minutes**."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est une **mesure d’équité** : elle rétablit une égalité **réelle** entre élèves en situation différente."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Mêmes cours, même règlement et école gratuite pour tous : **égalité**. Rampe, temps en plus et aide à la cantine : **équité**."}]$ex$::jsonb),
  ('fcdb2e20-7248-5c26-b40a-566f95c96d13'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Peut-on tout écrire sur le blog ?","competence":"analyser-document","situation":"Le blog du collège accepte les commentaires des élèves. Une délégation veut savoir lesquels sont permis par la loi et pourquoi les trois valeurs vont ensemble.","documents":[{"id":"blog","type":"dialogue","modele":"sms","titre":"Les commentaires du blog","participants":[{"nom":"Élève 1","emoji":"🧑","cote":"gauche"},{"nom":"Élève 2","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Élève 1","texte":"Je trouve qu’il manque des légumes à la cantine."},{"qui":"Élève 2","texte":"Pas d’accord avec le délégué : je pense que la sortie est trop chère."},{"qui":"Élève 1","texte":"Tais-toi ou je vais te casser la figure !"},{"qui":"Élève 2","texte":"Tu n’es qu’un abruti."}],"source":"Commentaires écrits pour l’exercice"},{"id":"trio","type":"tableau","titre":"Les trois valeurs, seules","colonnes":["Valeur seule","Ce qu’elle produit"],"lignes":[["La liberté totale","?"],["L’égalité absolue","?"],["La fraternité","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui fait de ce commentaire une menace.","aide":"Cherche ce que l’élève annonce qu’il va faire à l’autre.","type":"zone","document":"blog","multiple":false},{"enonce":"Range ces commentaires : permis, ou interdits par la loi ?","aide":"On peut critiquer ; on ne peut ni insulter, ni menacer, ni diffamer, ni appeler à la haine.","type":"categories","categories":[{"id":"c0","texte":"Permis"},{"id":"c1","texte":"Interdit par la loi"}],"items":[{"id":"i0","texte":"Il manque des légumes à la cantine"},{"id":"i1","texte":"Tu n’es qu’un abruti"},{"id":"i2","texte":"Je te casse la figure si tu parles"},{"id":"i3","texte":"Une fausse rumeur qui salit un camarade"},{"id":"i4","texte":"Il faut haïr les élèves de la 6e C"},{"id":"i5","texte":"Je ne suis pas d’accord avec le délégué"}]},{"enonce":"Relie chaque valeur seule à ce qu’elle produit.","aide":"Sans règles communes, les plus forts l’emportent ; sans choix, tout est identique.","type":"association","gauche":[{"id":"g0","texte":"La liberté totale"},{"id":"g1","texte":"L’égalité absolue"},{"id":"g2","texte":"La fraternité"}],"droite":[{"id":"d0","texte":"Elle supprime les choix"},{"id":"d1","texte":"Elle creuse les écarts"},{"id":"d2","texte":"Elle permet de tenir les deux ensemble"}]},{"enonce":"Un élève voit un camarade tomber et saigner dans la cour. Il ne fait rien alors qu’il pourrait appeler. Quel délit rattache la fraternité au droit ?","aide":"Il s’agit de ne pas aider quelqu’un en danger.","type":"choix","options":[{"id":"a","texte":"La non-assistance à personne en danger"},{"id":"b","texte":"Le vol de matériel scolaire"},{"id":"c","texte":"La diffamation envers un camarade"},{"id":"d","texte":"L’appel à la haine contre un groupe"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"« **Casser** la figure » est une menace : elle est interdite par la loi, même au nom de la liberté d’expression."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c1","i5":"c0"}},"explication":"Donner son avis est **permis** ; l’**insulte**, la **menace**, la **diffamation** et l’**appel à la haine** sont interdits."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**Liberté** totale : écarts. **Égalité** absolue : plus de choix. **Fraternité** : elle permet de tenir les deux ensemble."},{"cle":{"type":"choix","ids":["a"]},"explication":"La fraternité ne s’impose pas par la loi, mais la **non-assistance à personne en danger** est un délit."}]$ex$::jsonb),
  ('ebc93d31-f95a-5be1-a7e6-27c3575ae336'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"L’affiche du hall de Lila","competence":"analyser-document","situation":"Pour son premier jour de 6e, Lila voit une grande affiche dans le hall. Sa professeure principale lui explique ce que c’est.","documents":[{"id":"hall","type":"dialogue","modele":"bulles","titre":"Dans le hall du collège","participants":[{"nom":"Lila","emoji":"👧","cote":"gauche"},{"nom":"La professeure","emoji":"👩‍🏫","cote":"droite"}],"repliques":[{"qui":"Lila","texte":"C’est quoi, cette grande affiche ?"},{"qui":"La professeure","texte":"La Charte de la laïcité à l’école. Elle compte 15 articles et elle est affichée depuis 2013."},{"qui":"La professeure","texte":"La laïcité te laisse croire, ne pas croire, ou changer d’avis."},{"qui":"La professeure","texte":"La loi de séparation des Églises et de l’État date de 1905 : l’État ne finance aucun culte."}],"source":"Dialogue écrit pour l’exercice"}],"questions":[{"enonce":"Combien d’articles compte la Charte de la laïcité ?","aide":"La professeure donne le nombre dans sa première réponse.","type":"nombre","unite":"articles"},{"enonce":"Touche l’année de la loi qui sépare les Églises et l’État.","aide":"Cherche la date dans la dernière réplique.","type":"zone","document":"hall","multiple":false},{"enonce":"Relie chaque garantie de la laïcité à ce qu’elle veut dire.","aide":"Relis la deuxième réplique de la professeure, puis le tableau du cours.","type":"association","gauche":[{"id":"g0","texte":"La liberté de conscience"},{"id":"g1","texte":"La séparation"},{"id":"g2","texte":"L’égalité"}],"droite":[{"id":"d0","texte":"Entre l’État et les religions"},{"id":"d1","texte":"De tous devant la loi, quelle que soit la croyance"},{"id":"d2","texte":"Croire, ne pas croire, changer d’avis"}]}]}$ex$::jsonb,
