  ('ebc93d31-f95a-5be1-a7e6-27c3575ae336'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une lettre pour un correspondant étranger","competence":"analyser-texte","situation":"Camille explique la laïcité à son correspondant. Dans sa lettre, une phrase est fausse. Tu la repères et tu replaces les dates sur une frise.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"La lettre de Camille","auteur":"Texte écrit pour l’exercice","blocs":["Cher Jonas, chez nous, l’école publique est laïque.","À l’école, la laïcité interdit de parler des religions en cours, même en histoire.","Les enseignants restent neutres et les élèves sont libres de croire ou de ne pas croire."]},{"id":"frise","type":"frise","titre":"Trois dates","debut":1900,"fin":2020,"pas":10,"evenements":[{"id":"z1","date":1905,"nom":"Séparation"},{"id":"z2","date":2004,"nom":"Loi signes"},{"id":"z3","date":2013,"nom":"Charte"}]}],"questions":[{"enonce":"Touche le mot qui rend fausse la phrase de Camille sur les religions en cours.","aide":"Parler des religions en cours est prévu par les programmes.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche la date de la loi sur les signes religieux ostensibles à l’école.","aide":"Elle se situe au début des années 2000.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la loi de 1905 de la Charte de la laïcité ?","aide":"Soustrais 1905 à l’année de la Charte.","type":"nombre","unite":"ans"},{"enonce":"Range ces phrases : vraies ou fausses ?","aide":"L’État ne croit rien, ne combat aucune croyance et n’en finance aucune.","type":"categories","categories":[{"id":"c0","texte":"Vrai"},{"id":"c1","texte":"Faux"}],"items":[{"id":"i0","texte":"La Charte de la laïcité compte 15 articles"},{"id":"i1","texte":"La laïcité est une opinion contre les religions"},{"id":"i2","texte":"Un élève peut être dispensé d’un cours au nom de sa croyance"},{"id":"i3","texte":"Les enseignants doivent rester neutres"},{"id":"i4","texte":"La laïcité garantit aussi la liberté de ne croire en aucune religion"},{"id":"i5","texte":"L’État finance les cultes depuis 1905"}]}]}$ex$::jsonb,
